// 4 Царств — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["І відійшов Моав від Ізраїля після смерти Ахава.","Охозія ж упав через ґрати зі світлиці своєї, що в Самарії, і занедужав. І послав послів, і сказав їм: підіть, запитайте у Веельзевула, божества аккаронського: чи видужаю я від цієї хвороби? [І пішли вони запитувати.]","Тоді ангел Господній сказав Іллі фесвитянину: встань, піди назустріч посланим від царя Самарійського і скажи їм: хіба немає Бога в Ізраїлі, що ви йдете запитувати Веельзевула, божество аккаронське?","За це так говорить Господь: з постелі, на яку ти ліг, не встанеш з неї, але помреш. І пішов Ілля, [і сказав їм].","І повернулися до Охозії послані. І він сказав їм: чого це ви повернулися?","І сказали йому: назустріч нам вийшов чоловік і сказав нам: підіть, поверніться до царя, який послав вас, і скажіть йому: так говорить Господь: хіба немає Бога в Ізраїлі, що ти посилаєш запитувати Веельзевула, божество аккаронське? За те з постелі, на яку ти ліг, не встанеш з неї, але помреш.","І сказав їм: який на вигляд той чоловік, який вийшов назустріч вам і говорив вам слова ці?","Вони сказали йому: чоловік той весь у волоссі і шкіряним поясом підперезаний по стегнах своїх. І сказав він: це Ілля фесвитянин.","І послав до нього п’ятдесятника з його п’ятидесятком. І він пішов до нього, коли Ілля сидів на верхівці гори, і сказав йому: чоловіче Божий! цар говорить: зійди.","І відповідав Ілля, і сказав п’ятдесятникові: якщо я чоловік Божий, то нехай зійде вогонь з неба і попалить тебе і твій п’ятидесяток. І зійшов вогонь з неба і попалив його і п’ятидесяток його.","І послав до нього цар іншого п’ятдесятника з його п’ятидесятком. І він став говорити йому: чоловіче Божий! так сказав цар: зійди швидше.","І відповів Ілля і сказав йому: якщо я чоловік Божий, то нехай зійде вогонь з неба і попалить тебе і твій п’ятидесяток. І зійшов вогонь Божий з неба, і попалив його і п’ятидесяток його.","І ще послав утретє п’ятдесятника з його п’ятидесятком. І піднявся, і прийшов п’ятдесятник третій, і упав на коліна свої перед Іллею, і благав його, і говорив йому: чоловіче Божий! нехай не буде знехтувана душа моя і душі рабів твоїх — цих п’ятдесятьох — перед очима твоїми;","ось, зійшов вогонь з неба, і попалив двох п’ятдесятників попередніх з їх п’ятидесятками; але тепер нехай не буде знехтувана душа моя перед очима твоїми!","І сказав ангел Господній Іллі: піди з ним, не бійся його. І він встав, і пішов з ним до царя.","І сказав йому: так говорить Господь: за те, що ти посилав послів запитувати Веельзевула, божество аккаронське, ніби в Ізраїлі немає Бога, щоб запитувати про слово Його, — з постелі, на яку ти ліг, не встанеш з неї, але помреш.","І помер він за словом Господнім, що прорік Ілля. І став царем Іорам [брат Охозії], замість нього, на другий рік Іорама, сина Іосафатового, царя Юдейського, бо сина в того не було.","Інше про Охозію, що він зробив, написано в літописі царів ізраїльських."],"x":{"1":"9.8.2|11.3.5","2":"31.19.3|50.10.25|5.15.45","4":"25.54.24","8":"31.20.2|48.13.4|50.3.4","9":"6.13.6|10.17.18|71.6.11","10":"52.9.54|76.11.5","12":"52.9.54","17":"11.3.1","18":"13.22.1"}},{"v":["У той час, коли Господь захотів піднести Іллю у вихорі на небо, йшов Ілля з Єлисеєм з Галгала.","І сказав Ілля Єлисеєві: залишся тут, бо Господь посилає мене у Вефиль. Але Єлисей сказав: живий Господь і жива душа твоя! не залишу тебе. І пішли вони у Вефиль.","І вийшли сини пророків, що у Вефилі, до Єлисея і сказали йому: чи знаєш, що сьогодні Господь піднесе господаря твого над главою твоєю? Він сказав: я також знаю, мовчіть.","І сказав йому Ілля: Єлисею, залишся тут, бо Господь посилає мене в Єрихон. І сказав він: живий Господь і жива душа твоя! не залишу тебе. І прийшли в Єрихон.","І підійшли сини пророків, що у Єрихоні, до Єлисея і сказали йому: чи знаєш, що сьогодні Господь бере господаря твого і піднесе над главою твоєю? Він сказав: я також знаю, мовчіть.","І сказав йому Ілля: залишся тут, тому що Господь посилає мене до Йордану. І сказав він: живий Господь і жива душа твоя! не залишу тебе. І пішли обоє.","П’ятдесят чоловік із синів пророчих пішли і стали віддалік навпроти них, а вони обоє стояли біля Йордану.","І взяв Ілля милоть свою, і згорнув, і вдарив нею по воді, і розступилася вона туди і сюди, і перейшли обоє по сухому.","Коли вони перейшли, Ілля сказав Єлисеєві: проси, що зробити тобі, раніше, ніж я буду взятий від тебе. І сказав Єлисей: дух, який у тобі, нехай буде на мені подвійно.","І сказав він: важкого ти просиш. Якщо побачиш, як я буду взятий від тебе, то буде тобі так, а якщо не побачиш, не буде.","Коли вони йшли і дорогою розмовляли, раптом з’явилася колісниця вогненна і коні вогненні, і розлучили їх обох, і понісся Ілля у вихорі на небо.","Єлисей же дивився і викликнув: батьку мій, батьку мій, колісниця Ізраїля і кіннота його! І не бачив його більше. І схопив він одяг свій і роздер його на дві частини.","І підняв милоть Іллі, що впала з нього, і пішов назад, і став на березі Йордану;","і взяв милоть Іллі, що впала з нього, і вдарив нею по воді, і сказав: де Господь, Бог Іллі, — Він Самий? І вдарив по воді, і вона розступилася туди і сюди, і перейшов Єлисей.","І побачили його сини пророків, що у Єрихоні, здаля, і сказали: спочив дух Іллі на Єлисеєві. І пішли назустріч йому, і поклонилися йому до землі,","і сказали йому: ось, є у нас , рабів твоїх, чоловік п’ятдесят, люди сильні; нехай би вони пішли і пошукали господаря твого; може, відніс його Дух Господній і поставив його на одній з гір, або на одній з долин. Він же сказав: не посилайте.","Але вони приступали до нього довго, так що надокучили йому, і він сказав: пошліть. І послали п’ятдесят чоловік, і шукали три дні, і не знайшли його,","і повернулися до нього, тим часом як він залишався в Єрихоні, і сказав їм: чи не говорив я вам: не ходіть?","І сказали жителі того міста Єлисеєві: ось, розташування цього міста добре, як бачить господар наш; але вода погана і земля неплідна.","І сказав він: дайте мені нову чашу і покладіть туди соли. І дали йому.","І вийшов він до джерела води, і кинув туди соли, і сказав: так говорить Господь: Я зробив воду цю здоровою, не буде від неї надалі ні смерти, ні неплідности.","І вода стала здоровою до цього дня, за словом Єлисея, що він сказав.","І пішов він звідти у Вефиль. Коли він ішов дорогою, малі діти вийшли з міста і насміхалися з нього і говорили йому: йди, плішивий! йди, плішивий!","Він озирнувся і побачив їх і прокляв їх ім’ям Господнім. І вийшли дві ведмедиці з лісу і розірвали з них сорок дві дитини.","Звідси пішов він на гору Кармил, а звідти повернувся в Самарію."],"x":{"1":"4.11.30|5.4.19","2":"0.12.8|11.4.30|7.1.16","4":"4.34.3","8":"1.14.21|5.3.16|5.4.23","9":"10.3.5|51.6.22","11":"30.48.13|21.2.58","12":"75.11.5","15":"11.2.7|10.18.12","17":"11.8.11","19":"1.15.23","24":"4.18.19|25.43.6|29.11.18","25":"5.19.26"}},{"v":["Іорам, син Ахава, став царем над Ізраїлем у Самарії у вісімнадцятий рік Іосафата, царя Юдейського, і царював дванадцять років,","і робив невгодне в очах Господніх, хоча не так, як батько його і мати його: він зняв статую Ваала, яку зробив батько його;","однак же гріхів Ієровоама, сина Наватового, що ввів у гріх Ізраїля, він тримався, не відступав від них.","Меса, цар Моавитський, був багатий на худобу і посилав цареві Ізраїльському по сто тисяч овець і по сто тисяч необстрижених баранів.","Але коли помер Ахав, цар Моавитський відділився від царя Ізраїльського.","І виступив цар Іорам у той час із Самарії і зробив огляд всім ізраїльтянам;","і пішов і послав до Іосафата, царя Юдейського, сказати: цар Моавитський відділився від мене, чи підеш зі мною на війну проти Моава? Він сказав: піду; як ти, так і я, як твій народ, так і мій народ; як твої коні, так і мої коні.","І сказав: якою дорогою йти нам? Він сказав: дорогою пустелі Едомської.","І пішов цар Ізраїльський, і цар Юдейський, і цар Едомський, і йшли вони обходом сім днів, і не було води для війська і для худоби, що йшла за ними.","І сказав цар Ізраїльський: ох! скликав Господь трьох царів цих, щоб віддати їх у руку Моава.","І сказав Іосафат: чи немає тут пророка Господнього, щоб нам запитати Господа через нього? І відповів один із слуг царя Ізраїльського і сказав: тут Єлисей, син Сафатів, який подавав воду на руки Іллі.","І сказав Іосафат: є в нього слово Господнє. І пішли до нього цар Ізраїльський, і Іосафат, і цар Едомський.","І сказав Єлисей цареві Ізраїльському: що мені і тобі? піди до пророків батька твого і до пророків матері твоєї. І сказав йому цар Ізраїльський: ні, бо Господь скликав сюди трьох царів цих, щоб віддати їх у руки Моава.","І сказав Єлисей: живий Господь Саваоф, перед Яким я стою! Якби я не шанував Іосафата, царя Юдейського, то не глянув би на тебе і не бачив би тебе;","тепер покличте мені гусляра. І коли гусляр грав на гуслях, тоді рука Господня торкнулася Єлисея,","і він сказав: так говорить Господь: робіть на цій долині рови за ровами,","бо так говорить Господь: не побачите вітру і не побачите дощу, а долина ця наповниться водою, яку будете пити ви і дрібна і велика худоба ваша;","але цього мало перед очима Господа; Він і Моава віддасть у руки ваші,","і ви уразите всі міста укріплені і всі міста головні, і всі кращі дерева зрубаєте, і всі джерела водні загатите, і всі кращі ділянки польові зіпсуєте камінням.","Зранку, коли підносять хлібне приношення, раптом полилася вода по дорозі від Едома, і наповнилася земля водою.","Коли моавитяни почули, що йдуть царі воювати з ними, тоді зібрані були всі, починаючи від тих, хто носить пояс, і старші, і стали на кордоні.","Зранку встали вони рано, і коли сонце засяяло над водою, моавитянам здаля здалася ця вода червоною, як кров.","І сказали вони: це кров; побилися царі між собою і знищили один одного; тепер на здобич, Моав!","І прийшли вони до стану ізраїльського. І встали ізраїльтяни і почали бити моавитян, і ті побігли від них, а вони продовжували йти на них і бити моавитян.","І міста зруйнували, і на кожну кращу ділянку в полі кинули кожен по каменю і закидали його; і всі протоки вод загатили й усі дерева кращі зрубали, так що залишалися тільки камені в Кир-Харешеті. І обступили його пращники і зруйнували його.","І побачив цар Моавитський, що битва долає його, і взяв із собою сімсот чоловік, які володіють мечем, щоб пробитися до царя Едомського; але не могли.","І взяв він сина свого первістка, якому належало царювати замість нього, і підніс його у всепалення на стіні. Це спричинило велике обурення серед ізраїльтян, і вони відступили від нього і повернулися у свою землю."],"x":{"1":"11.1.17","2":"10.16.32","3":"10.12.28","5":"11.1.1|10.21.29","7":"10.22.4","9":"13.21.9","11":"10.22.5","14":"8.15.26","15":"8.16.16|11.4.27","20":"1.29.39","27":"0.22.2|2.20.2|25.105.37"}},{"v":["Одна з дружин синів пророчих із криком говорила Єлисеєві: раб твій, мій чоловік, помер; а ти знаєш, що раб твій боявся Господа; тепер прийшов позикодавець взяти обох дітей моїх у раби собі.","І сказав їй Єлисей: що мені зробити тобі? скажи мені, що є у тебе в домі? Вона сказала: немає в раби твоєї нічого в домі, крім посудини з єлеєм.","І сказав він: піди, попроси собі посудин на стороні, у всіх сусідів твоїх, посудин порожніх; набери чимало,","і піди, замкни двері за собою і за синами твоїми, і наливай в усі ці посудини; повні відставляй.","І пішла від нього і замкнула двері за собою і за синами своїми. Вони подавали їй, а вона наливала.","Коли були наповнені посудини, вона сказала синові своєму: подай мені ще посудину. Він сказав їй: немає більш посудин. І зупинилася олія.","І прийшла вона, і переказала чоловіку Божому. Він сказав: піди, продай олію і заплати борги твої; а що залишиться, тим будеш жити із синами твоїми.","Одного дня прийшов Єлисей у Сонам. Там одна багата жінка запросила його до себе їсти хліб; і коли б він не проходив, завжди заходив туди їсти хліб.","І сказала вона чоловіку своєму: ось, я знаю, що чоловік Божий, який проходить повз нас постійно, святий;","зробимо невелику світлицю над стіною і поставимо йому там постіль, і стіл, і сідалище, і світильник; і коли він буде приходити до нас, нехай заходить туди.","В один день він прийшов туди, і зайшов у світлицю, і ліг там,","і сказав Гиєзію, слузі своєму: поклич цю сонамитянку. І покликав її, і вона стала перед ним.","І сказав йому: скажи їй: «ось, ти так піклуєшся про нас; що зробити б тобі? чи не потрібно поговорити про тебе з царем, або з воєначальником?» Вона сказала: ні, серед свого народу я живу.","І сказав він: що ж зробити їй? І сказав Гиєзій: так ось, сина немає у неї, а чоловік її старий.","І сказав він: поклич її. Він покликав її, і стала вона у дверях.","І сказав він: через рік, у цей самий час ти будеш тримати на руках сина. І сказала вона: ні, господарю мій, чоловіче Божий, не обманюй раби твоєї.","І жінка стала вагітною і народила сина на другий рік, у той самий час, як сказав їй Єлисей.","І підріс хлопчик і в один день пішов до батька свого, до женців.","І сказав батькові своєму: голова моя! голова моя болить! І сказав той слузі своєму: віднеси його до матері його.","І поніс його і приніс його до матері його. І він сидів на колінах у неї до полудня, і помер.","І пішла вона, і поклала його на постелі чоловіка Божого, і замкнула його, і вийшла,","і покликала чоловіка свого і сказала: пришли мені одного зі слуг і одну з ослиць, я поїду до чоловіка Божого і повернуся.","Він сказав: навіщо тобі їхати до нього? сьогодні не новомісяччя і не субота. Але вона сказала: добре.","І осідлала ослицю і сказала слузі своєму: веди і йди; не зупиняйся, доки не скажу тобі.","І вирушила і прибула до чоловіка Божого, до гори Кармил. І коли побачив чоловік Божий її здаля, то сказав слузі своєму Гиєзію: це та сонамитянка.","Побіжи до неї назустріч і скажи їй: «чи здорова ти? чи здоровий чоловік твій? чи здорова дитина?» — Вона сказала: здорові.","Коли ж прийшла до чоловіка Божого на гору, схопилася за ноги його. І підійшов Гиєзій, щоб відвести її; але чоловік Божий сказав: залиш її, душа в неї засмучена, а Господь приховав від мене і не оголосив мені.","І сказала вона: чи просила я сина в господаря мого? чи не говорила я: «не обманюй мене»?","І сказав він Гиєзію: підпережи стегна твої і візьми жезл мій у руку твою, і піди; якщо зустрінеш кого, не вітай його, і якщо хто буде тебе вітати, не відповідай йому; і поклади жезл мій на лице дитини.","І сказала мати дитини: живий Господь і жива душа твоя! не відстану від тебе. І він встав і пішов за нею.","Гиєзій пішов попереду них і поклав жезл на лице дитини. Але не було ні голосу, ні відповіді. І вийшов назустріч йому, і доніс йому, і сказав: не пробуджується дитина.","І ввійшов Єлисей у дім, і ось, дитина померла лежить на постелі його.","І ввійшов, і замкнув двері за собою, і помолився Господу.","І піднявся і ліг над дитям, і приклав свої вуста до його вуст, і свої очі до його очей, і свої долоні до його долонь, і простягся на ньому, і зігрілося тіло хлопчика.","І встав і пройшов по світлиці назад і вперед; потім знову піднявся і простягся на ньому. І пчихнула дитина разів сім, і відкрила дитина очі свої.","І покликав він Гиєзія і сказав: поклич цю сонамитянку. І той покликав її. Вона прийшла до нього, і він сказав: візьми сина твого.","І підійшла, і впала йому в ноги, і поклонилася до землі; і взяла сина свого і пішла.","Єлисей же повернувся в Галгал. І був голод у землі тій, і сини пророків сиділи перед ним. І сказав він слузі своєму: постав великий казан і звари юшку для синів пророчих.","І вийшов один з них у поле збирати овочі, і знайшов дику витку рослину, і набрав з неї диких плодів повний одяг свій; і прийшов і накришив їх у казан з юшкою, тому що вони не знали їх .","І налили їм їсти. Але як тільки вони стали їсти юшку, то здійняли крик і говорили: смерть у казані, чоловіче Божий! І не могли їсти.","І сказав він: подайте борошна. І всипав його в казан і сказав [Гиєзію]: наливай людям, нехай їдять. І не стало нічого шкідливого в казані.","Прийшов хтось з Ваал-Шалиші, і приніс чоловіку Божому хлібний початок — двадцять ячмінних хлібців і сирі зерна в лушпинні. І сказав Єлисей: віддай людям, нехай їдять.","І сказав слуга його: що тут я дам сотні людей? І сказав він: віддай людям, нехай їдять, бо так говорить Господь: «наситяться, і залишиться».","Він подав їм, і вони наситилися, і ще залишилося, за словом Господнім."],"x":{"1":"2.25.39","2":"10.17.14","16":"0.18.10:14","18":"19.8.2","25":"5.19.46|11.2.25","27":"11.3.15","29":"52.10.4","35":"11.8.1","36":"10.17.22","37":"75.11.35","42":"3.18.19","43":"53.6.7","44":"50.15.37"}},{"v":["Неєман, воєначальник царя Сирійського, був великою людиною у господаря свого і шанованою, тому що через нього дав Господь перемогу сиріянам; і людина ця була відмінним воїном, але прокаженим.","Сиріяни одного разу пішли загонами і взяли в полон із землі Ізраїльської маленьку дівчинку, і вона служила дружині Неємановій.","І сказала вона господині своїй: о, якби господар мій побував у пророка, який у Самарії, то він зняв би з нього проказу його!","І пішов Неєман і передав це господарю своєму, говорячи: так і так говорить дівчинка, що із землі Ізраїльської.","І сказав цар Сирійський [Неєману]: піди, сходи, а я надішлю лист до царя Ізраїльського. Він пішов і взяв із собою десять талантів срібла і шість тисяч сиклів золота, і десять змін одягу;","і приніс лист цареві Ізраїльському, в якому було сказано: разом з листом цим, ось, я посилаю до тебе Неємана, слугу мого, щоб ти зняв з його проказу його.","Цар Ізраїльський, прочитавши лист, роздер одяг свій і сказав: хіба я Бог, щоб умертвляти й оживляти, що він посилає до мене, щоб я зняв з людини проказу її? ось, тепер знайте і дивіться, що він шукає приводу ворогувати проти мене.","Коли почув Єлисей, чоловік Божий, що цар Ізраїльський роздер одяг свій, то послав сказати цареві: для чого ти роздер одяг свій? нехай він прийде до мене, й дізнається, що є пророк в Ізраїлі.","І прибув Неєман на конях своїх і на колісниці своїй, і зупинився біля входу в дім Єлисєїв.","І вислав до нього Єлисей слугу сказати: піди, омийся сім разів у Йордані, й оновиться тіло твоє у тебе, і будеш чистий.","І розгнівався Неєман, і пішов, і сказав: ось, я думав, що він вийде, стане і закличе ім’я Господа Бога свого, і покладе руку свою на те місце і зніме проказу;","хіба Авана і Фарфар, ріки дамаські, не кращі за всі води ізраїльські? хіба я не міг би омитися в них і очиститися? І повернувся і відійшов у гніві.","І підійшли раби його і говорили йому, і сказали: батьку мій, якби що-небудь важливе сказав тобі пророк, то чи не зробив би ти? а тим більше, коли він сказав тобі тільки: «омийся, і будеш чистий».","І пішов він і занурився в Йордані сім разів, за словом чоловіка Божого, й оновилося тіло його, як тіло малої дитини, і очистився.","І повернувся до чоловіка Божого він і всі, хто супроводжував його, і прийшов, і став перед ним, і сказав: ось, я пізнав, що на всій землі немає Бога, як тільки в Ізраїля; отже, прийми дар від раба твого.","І сказав він: живий Господь, перед лицем Якого стою! не прийму. І той примушував його взяти, але він не погодився.","І сказав Неєман: якщо вже не так, то нехай рабові твоєму дадуть землі, скільки понесуть два мули, тому що не буде надалі раб твій приносити всепалення і жертви іншим богам, крім Господа;","тільки ось у чому нехай простить Господь раба твого: коли піде господар мій у дім Риммона для поклоніння там і обіпреться на руку мою, і поклонюся я в домі Риммона, то, за моє поклоніння в домі Риммона, нехай простить Господь раба твого у випадку цьому.","І сказав йому: йди з миром. І він від’їхав від нього на невеликий простір землі.","І сказав Гиєзій, слуга Єлисея, чоловіка Божого: ось, господар мій відмовився взяти з руки Неємана, цього сиріянина, те, що він приносив. Живий Господь! Побіжу я за ним, і візьму в нього що-небудь.","І погнався Гиєзій за Неєманом. І побачив Неєман того, хто біг за ним, і зійшов з колісниці назустріч йому, і сказав: чи з миром?","Він відповів: з миром; господар мій послав мене сказати: «ось, тепер прийшли до мене з гори Єфремової два молодих чоловіка із синів пророчих; дай їм талант срібла і дві зміни одягу».","І сказав Неєман: візьми, мабуть, два таланти. І просив його. І зав’язав він два таланти срібла у два мішки і дві зміни одягу і віддав двом слугам своїм, і понесли перед ним.","Коли він прийшов до пагорба, то взяв з рук їхніх і сховав удома. І відпустив людей, і вони пішли.","Коли він прийшов і з’явився до господаря свого, Єлисей сказав йому: звідки, Гиєзію? І сказав він: нікуди не ходив раб твій.","І сказав він йому: хіба серце моє не супроводжувало тебе, коли обернувся назустріч тобі чоловік той з колісниці своєї? чи час брати срібло і брати одяг, або оливкові дерева і виноградники, і дрібну або велику худобу, і рабів або рабинь?","Нехай же проказа Неєманова пристане до тебе і до потомства твого навік. І вийшов він від нього білий від прокази, як сніг."],"x":{"7":"4.32.39","10":"53.9.7|52.17.14","14":"52.4.27","15":"5.15.19|8.25.27","27":"9.3.29|1.4.6|3.12.10"}},{"v":["І сказали сини пророків Єлисеєві: ось, місце, де ми живемо при тобі, тісне для нас;","підемо до Йордану і візьмемо звідти кожен по одній колоді і зробимо собі там місце для житла. Він сказав: підіть.","І сказав один: зроби милість, піди і ти з рабами твоїми. І сказав він: піду.","І пішов з ними, і прийшли до Йордану і стали рубати дерева.","І коли один валив колоду, сокира його впала у воду. І закричав він і сказав: ох, господарю мій! а вона була позичена!","І сказав чоловік Божий: де вона впала? Він показав йому місце. І відрубав він шматок дерева і кинув туди, і сплила сокира.","І сказав він: візьми собі. Він простягнув руку свою і взяв її.","Цар Сирійський пішов війною на ізраїльтян, і радився зі слугами своїми, говорячи: у такому-то й у такому-то місці я розташую свій стан.","І посилав чоловік Божий до царя Ізраїльського сказати: бережися проходити цим місцем, тому що там сиріяни залягли.","І посилав цар Ізраїльський на те місце, про яке говорив йому чоловік Божий і застерігав його; і зберіг себе там не раз і не два.","І збентежилося серце царя Сирійського з цього приводу, і покликав він рабів своїх і сказав їм: скажіть мені, хто з наших у зносинах з царем Ізраїльським?","І сказав один із слуг його: ніхто, господарю мій царю; а Єлисей пророк, який у Ізраїля, переказує цареві Ізраїльському і ті слова, що ти говориш у спальній кімнаті твоїй.","І сказав він: підіть, дізнайтеся, де він; я пошлю і візьму його. І донесли йому і сказали: ось, він у Дофаїмі.","І послав туди коней і колісниці і багато війська. І прийшли вночі й оточили місто.","Вранці слуга чоловіка Божого встав і вийшов; і ось, військо навколо міста, і коні і колісниці. І сказав йому слуга його: горе нам! господарю мій, що нам робити?","І сказав він: не бійся, тому що тих, які з нами, більше, ніж тих, які з ними.","І молився Єлисей, і говорив: Господи! відкрий йому очі, щоб він побачив. І відкрив Господь очі слузі, і він побачив, і ось, уся гора наповнена конями і колісницями вогненними навкруги Єлисея.","Коли пішли до нього сиріяни, Єлисей помолився Господу і сказав: уразь їх сліпотою. І Він уразив їх сліпотою за словом Єлисея.","І сказав їм Єлисей: це не та дорога і не те місто; йдіть за мною, і я проведу вас до тієї людини, яку ви шукаєте. І привів їх у Самарію.","Коли вони прийшли у Самарію, Єлисей сказав: Господи! відкрий очі їм, щоб вони бачили. І відкрив Господь очі їхні, і побачили, що вони всередині Самарії.","І сказав цар Ізраїльський Єлисеєві, побачивши їх: чи не побити їх, батьку мій?","І сказав він: не вбивай. Хіба мечем твоїм і луком твоїм ти полонив їх, щоб убивати їх? Запропонуй їм хліба і води; нехай їдять і п’ють, і підуть до господаря свого.","І приготував їм великий обід, і вони їли і пили. І відпустив їх, і пішли до господаря свого. І не ходили більше ті полчища сирійські в землю Ізраїлеву.","Після того зібрав Венадад, цар Сирійський, усе військо своє і виступив, і обложив Самарію.","І був великий голод у Самарії, коли вони облягли її, так що осляча голова продавалася за вісімдесят сиклів срібла, і четверта частина каба голубиного посліду — по п’ять сиклів срібла.","Один раз цар Ізраїльський проходив по стіні, і жінка з криком говорила йому: допоможи, господарю мій царю.","І сказав він: якщо не допоможе тобі Господь, з чого я допоможу тобі? чи з току, а чи з точила?","І сказав їй цар: що тобі? І сказала вона: ця жінка говорила мені: «віддай свого сина, ми з’їмо його сьогодні, а сина мого з’їмо завтра».","І зварили ми мого сина, і з’їли його. І я сказала їй на другий день: «віддай же твого сина, і з’їмо його». Але вона сховала свого сина.","Цар, вислухавши слова жінки, роздер одяг свій: і проходив він по стіні, і народ бачив, що веретище на самому тілі його.","І сказав: нехай те і те зробить мені Бог, і ще більше зробить, якщо залишиться голова Єлисея, сина Сафатового, на ньому сьогодні.","Єлисей же сидів у своєму домі, і старці сиділи в нього. І послав [цар] людину від себе. Раніше, ніж прийшов посланий до нього, він сказав старцям: чи бачите, що цей син убивці послав зняти з мене голову? Дивіться, коли прийде посланий, зачиніть двері і притисніть його дверима. А ось і тупіт ніг господаря його за ним!","Ще говорив він з ними, і ось посланий приходить до нього, і говорить: ось яка біда від Господа! чого мені надалі чекати від Господа?"],"x":{"1":"11.4.38","13":"0.37.17","16":"13.32.7|58.4.4","17":"3.24.4|54.27.23|75.1.14","18":"0.19.11","22":"10.20.31|26.25.22|62.12.20","25":"11.7.18","28":"4.28.53","29":"2.26.29|33.4.10|36.5.10","30":"11.5.7"}},{"v":["І сказав Єлисей: вислухайте слово Господнє: так говорить Господь: завтра в цей час міра борошна кращого буде по сиклю і дві міри ячменю по сиклю біля воріт Самарії.","І відповів сановник, на руку якого цар спирався, чоловіку Божому, і сказав: якби Господь і відкрив вікна на небі, і тоді чи може це бути? І сказав той: ось побачиш очима твоїми, але їсти цього не будеш.","Чотири чоловіка прокажених знаходилися біля входу у ворота і говорили вони один одному: навіщо нам сидіти тут, очікуючи смерти?","Якщо зважитися нам піти в місто, то в місті голод, і ми там помремо; якщо ж сидіти тут, то також помремо. Підемо краще в стан сирійський. Якщо залишать нас у живих, будемо жити, а якщо умертвлять, помремо.","І встали в сутінках, щоб іти в стан сирійський. І прийшли до краю стану сирійського, і ось, немає там жодної людини.","Господь зробив те, що стану сирійському почувся стукіт колісниць та іржання коней, шум війська великого. І сказали вони один одному: очевидно, найняв проти нас цар Ізраїльський царів хеттейських і єгипетських, щоб піти на нас.","І встали і побігли в сутінках, і залишили намети свої, і коней своїх, і ослів своїх, весь стан, як він був, і побігли, рятуючи себе.","І прийшли ті прокажені до краю стану, і ввійшли в один намет, і їли і пили, і взяли звідти срібло, і золото, і одяг, і пішли і сховали. Пішли ще в інший намет, і там узяли, і пішли і сховали.","І сказали один одному: не так ми робимо. День цей — день радісної звістки, якщо ми будемо баритися і будемо чекати ранкового світла, то впаде на нас провина. Ходімо ж і повідомимо дім царський.","І прийшли, і покликали воротарів міських, і розповіли їм, говорячи: ми ходили в стан сирійський, і ось, немає там ні людини, ні голосу людського, а тільки коні прив’язані, і осли прив’язані, і намети, як бути їм.","І покликали воротарів, і вони передали звістку в самий палац царський.","І встав цар уночі, і сказав слугам своїм: скажу вам, що роблять з нами сиріяни. Вони знають, що ми терпимо голод, і вийшли зі стану, щоб сховатися в полі, думаючи так: «коли вони вийдуть з міста, ми захопимо їх живими і ввійдемо в місто».","І відповів один зі службовців при ньому, і сказав: нехай візьмуть п’ять з останніх коней, що залишилися в місті, [з усього ополчення ізраїльтян тільки і залишилося в ньому, з усього ополчення ізраїльтян, що загинуло], і пошлемо, і подивимося.","І взяли дві пари коней, запряжених у колісниці. І послав цар услід сирійському війську, сказавши: підіть, подивіться.","І їхали за ним до Йордану, і ось уся дорога встелена одягом і речами, які покидали сиріяни при поспішній утечі своїй. І повернулися послані, і донесли цареві.","І вийшов народ, і розграбував стан сирійський, і була міра борошна кращого по сиклю, і дві міри ячменю по сиклю, за словом Господнім.","І цар поставив того сановника, на руку якого спирався, біля воріт; і розтоптав його народ у воротах, і він помер, як сказав чоловік Божий, який говорив, коли приходив до нього цар.","Коли говорив чоловік Божий царю так: «дві міри ячменю по сиклю, і міра борошна кращого по сиклю будуть завтра в цей час біля воріт Самарії»,","тоді відповів цей сановник чоловіку Божому і сказав: «якби Господь і відкрив вікна на небі, і тоді чи може це бути?» А він сказав: «побачиш твоїми очима, але їсти цього не будеш».","Так і збулося з ним; і затоптав його народ у воротах, і він помер."],"x":{"2":"11.5.18","3":"2.13.46","6":"11.19.7","17":"11.7.2","19":"11.7.2"}},{"v":["І говорив Єлисей жінці, сина якої воскресив він, і сказав: устань, і піди, ти і дім твій, і поживи там, де можеш пожити, бо послав Господь голод, і він прийде на цю землю на сім років.","І встала та жінка, і зробила за словом чоловіка Божого; і пішла вона і дім її, і жила в землі Филистимській сім років.","Через сім років повернулася ця жінка з землі Филистимської і прийшла просити царя про дім свій і про поле своє.","Цар тоді розмовляв з Гиєзієм, слугою чоловіка Божого, і сказав: розкажи мені про все чудове, що́ зробив Єлисей.","І в той час як він розповідав цареві, що той воскресив померлого, жінка, сина якої воскресив він, просила царя про дім свій і про поле своє. І сказав Гиєзій: господарю мій царю, це та сама жінка і той самий син її, якого воскресив Єлисей.","І запитав цар у жінки, і вона розповіла йому. І дав їй цар одного з придворних, сказавши: поверніть їй усе, приналежне їй, і всі доходи з поля, з того дня, як вона залишила землю, понині.","І прийшов Єлисей у Дамаск, коли Венадад, цар Сирійський, був хворий. І донесли йому, говорячи: прийшов чоловік Божий сюди.","І сказав цар Азаїлу: візьми в руку твою дарунок і піди назустріч чоловіку Божому, і запитай Господа через нього, говорячи: чи видужаю я від цієї хвороби?","І пішов Азаїл назустріч йому, і взяв дарунок у руку свою і все краще в Дамаску, скільки можуть нести сорок верблюдів, і прийшов і став перед лицем його, і сказав: син твій Венадад, цар Сирійський, послав мене до тебе запитати: «чи видужаю я від цієї хвороби?»","І сказав йому Єлисей: піди, скажи йому: «видужаєш»; однак же відкрив мені Господь, що він помре.","І спрямував на нього Єлисей погляд свій, і так залишався до того, що привів його в ніяковість; і заплакав чоловік Божий.","І сказав Азаїл: від чого господар мій плаче? І сказав він: від того, що я знаю, яке зло вчиниш ти синам Ізраїлевим; фортеці їхні віддаси вогню, і юнаків їхніх мечем умертвиш, і немовлят їхніх поб’єш, і вагітних жінок їхніх розрубаєш.","І сказав Азаїл: що таке раб твій, пес [мертвий], щоб міг зробити таку велику справу? І сказав Єлисей: указав мені Господь у тобі царя Сирії.","І пішов він від Єлисея, і прийшов до господаря свого. І сказав йому цей : що говорив тобі Єлисей? І сказав: він говорив мені, що ти видужаєш.","А на другий день він узяв ковдру, намочив її водою, і поклав на лице його, і він помер. І став царем Азаїл замість нього.","У п’ятий рік Іорама, сина Ахавового, царя Ізраїльського, після Іосафата, царя Юдейського, став царем Іорам, син Іосафата, царя Юдейського.","Тридцяти двох років був він, коли став царем, і вісім років царював у Єрусалимі,","і ходив шляхом царів ізраїльських, як робив дім Ахавів, тому що дочка Ахава була дружиною його, і робив неугодне в очах Господніх.","Однак же не хотів Господь погубити Іуду, заради Давида, раба Свого, бо Він обіцяв дати йому світильник у дітях його на усі часи.","У дні його виступив Едом з-під руки Іуди, і поставили вони над собою царя.","І пішов Іорам у Цаїр, і всі колісниці з ним; і встав він уночі, й уразив ідумеян, які оточували його, і начальників над колісницями, але народ утік у намети свої.","І виступив Едом з-під руки Іуди до цього дня. У той же час виступила і Ливна.","Інше про Іорама і про все, що він зробив, написано в літописі царів юдейських.","І спочив Іорам з батьками своїми, і похований з батьками своїми в місті Давидовому. І став царем Охозія, син його, замість нього.","У дванадцятий рік Іорама, сина Ахавового, царя Ізраїльського, став царем Охозія, син Іорама, царя Юдейського.","Двадцяти двох років був Охозія, коли став царем, і один рік царював в Єрусалимі. Ім’я ж матері його Гофолія, дочка Амврія, царя Ізраїльського.","І ходив шляхом дому Ахавового, і робив неугодне в очах Господніх, подібно до дому Ахава, тому що він був родичем дому Ахавового.","І пішов він з Іорамом, сином Ахавовим, на війну з Азаїлом, царем Сирійським, у Рамоф галаадський, і поранили сиріяни Іорама.","І повернувся Іорам цар, щоб лікуватися в Ізреелі від ран, що заподіяли йому сиріяни в Рамофі, коли він воював з Азаїлом, царем Сирійським. І Охозія, син Іорама, цар Юдейський, прийшов відвідати Іорама, сина Ахавового, в Ізреель, тому що він був хворий."],"x":{"1":"11.4.35","8":"11.5.5","11":"11.2.17|32.14.17|52.19.41","12":"11.10.32","13":"10.19.15","16":"13.21.3","17":"13.21.20","18":"11.16.3|13.18.1","19":"9.7.16","20":"0.27.40|13.21.8","22":"5.21.13","24":"13.22.1","26":"11.11.1","27":"13.22.3","28":"10.22.29","29":"11.9.15"}},{"v":["Єлисей пророк покликав одного із синів пророчих і сказав йому: опережи стегна твої, і візьми цю посудину з єлеєм у руку твою, і піди в Рамоф галаадський.","Прийшовши туди, знайди там Іиуя, сина Іосафата, сина Намессієвого, і підійди, і повели йому виступити із середовища братів своїх, і введи його у внутрішню кімнату;","і візьми посудину з єлеєм, і вилий на голову його, і скажи: «так говорить Господь: помазую тебе на царя над Ізраїлем». Потім відчини двері, і біжи, і не чекай.","І пішов отрок, слуга пророка, у Рамоф галаадський,","і прийшов, і ось сидять воєначальники. І сказав: у мене слово до тебе, воєначальнику. І сказав Іиуй: до кого з усіх нас? І сказав він: до тебе, воєначальнику.","І встав він, і ввійшов у дім. І отрок вилив єлей на голову його, і сказав йому: так говорить Господь Бог Ізраїлів: «помазую тебе на царя над народом Господнім, над Ізраїлем,","і ти знищиш дім Ахава, господаря твого, щоб Мені помститися за кров рабів Моїх пророків і за кров усіх рабів Господніх, які впали від руки Ієзавелі;","і загине весь дім Ахава, і знищу в Ахава, хто мочиться до стіни, й ув’язненого і хто залишився в Ізраїлі,","і зроблю дім Ахава, як дім Ієровоама, сина Наватового, і як дім Вааси, сина Ахиїного;","Ієзавель же з’їдять пси на полі Ізреельському, і ніхто не поховає її». І відчинив двері, і втік.","І вийшов Іиуй до слуг господаря свого, і сказали йому: чи з миром? Навіщо приходив цей несамовитий до тебе? І сказав їм: ви знаєте цю людину і що він говорить.","І сказали: неправда, скажи нам. І сказав він: те і те він сказав мені, говорячи: «так говорить Господь: помазую тебе на царя над Ізраїлем».","І поспішили вони, і взяли кожен одяг свій, і підстелили йому на самих сходинках, і засурмили трубою, і сказали: царем став Іиуй!","І повстав Іиуй, син Іосафата, сина Намессієвого, проти Іорама; Іорам же знаходився з усіма ізраїльтянами в Рамофі галаадському на сторожі проти Азаїла, царя Сирійського.","Втім, сам цар Іорам повернувся, щоб лікуватися в Ізреелі від ран, які заподіяли йому сиріяни, коли він воював з Азаїлом, царем Сирійським. І сказав Іиуй: якщо ви згодні [зі мною], то нехай ніхто не виходить з міста, щоб іти подати звістку в Ізреелі.","І сів Іиуй на коня, і поїхав у Ізреель, де лежав Іорам [цар Ізраїльський, для лікування ран, які заподіяли йому сиріяни в Рамофі, коли він воював з Азаїлом, царем Сирійським, сильним і могутнім], і куди Охозія, цар Юдейський, прийшов відвідати Іорама.","На вежі в Ізреелі стояв сторож, і побачив він полчище Іиуєве, коли воно йшло, і сказав: полчище бачу я. І сказав Іорам: візьми вершника, і пошли назустріч їм, і нехай скаже: чи з миром?","І виїхав вершник на коні назустріч йому, і сказав: так говорить цар: чи з миром? І сказав Іиуй: що тобі до миру? Їдь за мною. І доніс сторож, і сказав: доїхав до них, але не повертається.","І послали іншого вершника, і він приїхав до них, і сказав: так говорить цар: чи з миром? І сказав Іиуй: що тобі до миру? Їдь за мною.","І доніс сторож, сказавши: доїхав до них, і не повертається, а хода, начебто Іиуя, сина Намессієвого, тому що він іде стрімко.","І сказав Іорам: запрягай. І запрягли колісницю його. І виступив Іорам, цар Ізраїльський, і Охозія, цар Юдейський, кожен на колісниці своїй. І виступили назустріч Іиую, і зустрілися з ним на полі Навуфея ізреелитянина.","І коли побачив Іорам Іиуя, то сказав: чи з миром Іиуй? І сказав він: який мир при любодійстві Ієзавелі, матері твоєї, і при багатьох волхвуваннях її?","І повернув Іорам руки свої, і побіг, і сказав Охозії: зрада, Охозіє!","А Іиуй натягнув лук рукою своєю, і вразив Іорама між плечима його, і пройшла стріла через серце його, й упав він на колісниці своїй.","І сказав Іиуй Бидекару, сановникові своєму: візьми, кинь його на ділянку поля Навуфея ізреелитянина, бо згадай, як ми з тобою їхали удвох позаду Ахава, батька його, і як Господь прорік на нього таке пророцтво:","істинно, кров Навуфея і кров синів його бачив Я вчора, говорить Господь, і помщуся тобі на цьому полі. Отже, візьми, кинь його на полі, за словом Господнім.","Охозія, цар Юдейський, побачивши це, побіг по дорозі до дому, що в саду. І погнався за ним Іиуй, і сказав: і його бийте на колісниці. Це було на висоті Гур, що при Івлеамі. І побіг він у Мегиддон, і помер там.","І відвезли його раби його в Єрусалим, і поховали його в гробниці його, з батьками його, у місті Давидовому.","В одинадцятий рік Іорама, сина Ахавового, став царем Охозія в Юдеї.","І прибув Іиуй у Ізреель. Ієзавель же, одержавши звістку, нарум’янила обличчя своє і прикрасила голову свою, і дивилася у вікно.","Коли Іиуй ввійшов у ворота, вона сказала: чи мир Замврію, убивці володаря свого?","І підняв він лице своє до вікна і сказав: хто зі мною, хто? І виглянули до нього два, три євнухи.","І сказав він: викиньте її. І викинули її. І бризнула кров її на стіну і на коней, і розтоптали її.","І прийшов Іиуй, і їв, і пив, і сказав: знайдіть цю прокляту і поховайте її, оскільки царська дочка вона.","І пішли ховати її, і не знайшли від неї нічого, крім черепа, і ніг, і кісток рук.","І повернулися, і донесли йому. І сказав він: таке було слово Господа, яке Він прорік через раба Свого Іллю фесвитянина, сказавши: на полі ізреельському з’їдять пси тіло Ієзавелі,","і буде труп Ієзавелі на ділянці ізреельській, як гній на полі, так що ніхто не скаже: це Ієзавель."],"x":{"1":"10.18.46|11.4.29","2":"10.19.16","6":"13.22.7","7":"10.21.22|38.1.4|76.2.20","8":"10.21.21","9":"10.15.29","10":"10.21.23","14":"10.19.16-17","15":"11.8.29","16":"11.8.29|13.22.6","17":"36.33.2","21":"10.21.1","22":"75.12.14","24":"13.22.8","26":"10.22.38","27":"13.22.9|5.17.11","31":"10.16.10","33":"10.21.23","34":"10.16.31","35":"10.21.23","36":"10.21.23"}},{"v":["У Ахава було сімдесят синів у Самарії. І написав Іиуй листа, і послав у Самарію до начальників Ізреельських, старійшин і вихователів дітей Ахавових, такого змісту:","коли прийде цей лист до вас, то, оскільки у вас і сини господаря вашого, у вас же і колісниці, і коні, й укріплене місто, і зброя, —","виберіть кращого і найдостойнішого із синів володаря свого, і посадіть на престіл батька його, і воюйте за дім володаря свого.","Вони злякалися надзвичайно і сказали: ось, два царі не устояли перед ним, як же нам устояти?","І послав начальник над домом царським , і градоначальник, і старійшини, і вихователі до Іиуя, сказати: ми раби твої, і що скажеш нам, те і зробимо; ми нікого не поставимо царем, що завгодно тобі, те і роби.","І написав він до них лист удруге такий: якщо ви мої і слову моєму підкорюєтеся, то візьміть голови синів володаря свого, і прийдіть до мене завтра в цей час у Ізреель. [Царських же синів було сімдесят чоловік; виховували їх найзнатніші в місті.]","Коли прийшов до них лист, вони взяли царських синів, і закололи їх — сімдесят чоловік, і поклали голови їхні у кошики, і послали до нього в Ізреель.","І прийшов посланий, і доніс йому, і сказав: принесли голови синів царських. І сказав він: розкладіть їх на дві купи біля входу у ворота, до ранку.","Зранку він вийшов, і став, і сказав усьому народу: ви невинні. Ось я повстав проти володаря мого й умертвив його, а їх усіх хто убив?","Знайте ж тепер, що не падає на землю жодне слово Господа, яке Він прорік про дім Ахава; Господь зробив те, що прорік через раба Свого Іллю.","І умертвив Іиуй усіх, хто залишився з дому Ахава в Ізреелі, й усіх вельмож його, і близьких його, і священиків його, так що не залишилося від нього жодного вцілілого.","І встав, і пішов, і прийшов у Самарію. Знаходячись на дорозі при Беф-Екеді пастушому,","зустрів Іиуй братів Охозії, царя Юдейського, і сказав: хто ви? Вони сказали: ми брати Охозії, йдемо довідатися про здоров’я синів царя і синів господині.","І сказав він: візьміть їх живих. І взяли їх живих, і закололи їх — сорок два чоловіка, біля колодязя Беф-Екеда, і не залишилося з них жодного.","І поїхав звідти, і зустрівся з Іонадавом, сином Рихавовим, який ішов назустріч йому, і вітав його, і сказав йому: чи налаштоване твоє серце так, як моє серце до твого серця? І сказав Іонадав: так. Якщо так, то дай руку твою. І подав він руку свою, і підняв він його до себе в колісницю,","і сказав: їдь зі мною, і дивися на мою ревність за Господа. І посадили його в колісницю.","Прибувши в Самарію, він убив усіх, хто залишався в Ахава в Самарії, так що зовсім знищив його, за словом Господа, яке Він прорік Іллі.","І зібрав Іиуй весь народ і сказав їм: Ахав мало служив Ваалу; Іиуй буде служити йому більше.","Отже, скличте до мене всіх пророків Ваала, всіх служителів його і всіх священиків його, щоб ніхто не був відсутнім, тому що в мене буде велика жертва Ваалу. А всякий, хто не з’явиться, не залишиться живим. Іиуй робив це з хитрим наміром, щоб знищити служителів Ваала.","І сказав Іиуй: призначте святкове зібрання заради Ваала. І проголосили зібрання .","І послав Іиуй по всьому Ізраїлю, і прийшли всі служителі Ваала; не залишалося жодного чоловіка, хто не прийшов би; і ввійшли в дім Ваалів, і наповнився дім Ваалів від краю до краю.","І сказав він хранителеві одягу: принеси одяг для всіх служителів Ваала. І він приніс їм одяг.","І ввійшов Іиуй з Іонадавом, сином Рихавовим, у дім Ваалів, і сказав служителям Ваала: розвідайте і розгляньте, чи не знаходиться серед вас хто-небудь із служителів Господніх, тому що тут повинні знаходитися тільки одні служителі Ваала.","І приступили вони до звершення жертв і всепалень. А Іиуй поставив поза домом вісімдесят чоловік і сказав: душа того, в якого врятується хто-небудь з людей, яких я віддаю вам у руки, буде замість душі того, хто врятується .","Коли закінчено було всепалення, сказав Іиуй скороходам і начальникам: підіть, бийте їх, щоб жоден не втік. І вразили їх вістрям меча і кинули їх скороходи і начальники, і пішли в місто, де було капище Ваалове.","І винесли ідолів з капища Ваалового і спалили їх.","І розбили ідола Ваала, і зруйнували капище Ваалове; і зробили з нього місце нечистот, до цього дня.","І знищив Іиуй Ваала з землі Ізраїльської.","Втім, від гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх, від них не відступав Іиуй, — від золотих тельців, які у Вефилі і які в Дані.","І сказав Господь Іиую: за те, що ти охоче зробив, що було праведним в очах Моїх, виконав над домом Ахавовим усе, що було на серці в Мене, сини твої до четвертого роду будуть сидіти на престолі Ізраїлевім.","Але Іиуй не намагався ходити в законі Господа Бога Ізраїлевого, від усього серця. Він не відступав від гріхів Ієровоама, який увів Ізраїля в гріх.","У ті дні почав Господь відрізати частини від ізраїльтян, і вражав їх Азаїл по всьому краю Ізраїлевому,","на схід від Йордану, всю землю Галаад, коліно Гадове, Рувимове, Манассіїне, починаючи від Ароера, що при потоці Арноні, і Галаад і Васан.","Інше про Іиуя і про все, що він зробив, і про мужні подвиги його написано в літописі царів ізраїльських.","І спочив Іиуй з батьками своїми, і поховали його в Самарії. І став царем Іоахаз, син його, замість нього.","Часу ж царювання Іиуєвого над Ізраїлем, у Самарії, було двадцять вісім років."],"x":{"4":"11.9.21:27","10":"10.8.56","13":"13.22.8","14":"38.1.4","15":"32.35.6","16":"10.19.10","17":"10.21.21","18":"10.16.32","24":"10.20.39","25":"10.18.40","26":"4.7.5|4.12.3|11.11.18","29":"10.12.30|11.13.2:11","30":"11.15.12","31":"10.15.26","32":"10.19.17|11.8.12","34":"13.22.7"}},{"v":["Гофолія, мати Охозії, бачачи, що син її помер, встала і знищила все царське плем’я.","Але Іосавеф, дочка царя Іорама, сестра Охозії, взяла Іоаса, сина Охозії, і таємно вивела його із середовища синів царських, яких умертвляли, його і годувальницю його, у постільну кімнату; і сховали його від Гофолії, і він не був умертвлений.","І був він з нею переховуваним у домі Господньому шість років, тим часом як Гофолія царювала над землею.","У сьомий рік послав Іодай, і взяв сотників з охоронців і скороходів, і привів їх до себе в дім Господній, і уклав з ними договір, і взяв з них клятву в домі Господньому, і показав їм царського сина.","І дав їм наказ, сказавши: ось що ви зробіть: третя частина з вас, із тих, хто приходить у суботу, буде нести сторожу при царському домі;","третя частина біля воріт Сур, і третя частина біля воріт позаду охоронців, і утримуйте варту дому, щоб не було пошкодження;","і дві частини з вас, з усіх, хто відходить у суботу, будуть нести сторожу при домі Господньому для царя;","і оточіть царя з усіх боків, кожен зі зброєю своєю в руці своїй; і хто б не ввійшов у ряди, той нехай буде умертвленим. І будьте при цареві, коли він виходить і коли входить.","І зробили сотники все, що наказав Іодай священик, і взяв кожен людей своїх, які приходять у суботу і відходять у суботу, і прийшли до Іодая священика.","І роздав священик сотникам списи і щити царя Давида, що були в домі Господньому.","І стали скороходи, кожен зі зброєю в руці своїй, від правої сторони дому до лівої сторони дому, біля жертовника й біля дому, навколо царя.","І вивів він царського сина, і поклав на нього царський вінець і прикраси, і поставили його царем, і помазали його, і плескали в долоні і викликували: нехай живе цар!","І почула Гофолія голос народу, що біг, і пішла до народу в дім Господній.","І бачить, і ось цар стоїть на підвищенні, за звичаєм, і князі і труби поруч царя; і весь народ землі веселиться, і сурмлять трубами. І роздерла Гофолія одяг свій, і закричала: змова! змова!","І дав наказ Іодай священик сотникам, які начальствують над військом, і сказав їм: «виведіть її за ряди, а хто піде за нею, умертвляйте мечем», тому що думав священик, щоб не умертвили її в домі Господньому.","І дали їй місце, і вона пройшла через вхід кінський до дому царського, й умертвили її там.","І уклав Іодай завіт між Господом і між царем і народом, щоб він був народом Господнім, і між царем і народом.","І пішов весь народ землі в дім Ваала, і зруйнували жертовники його, і зображення його зовсім розбили, і Матфана, жерця Ваалового, убили перед жертовниками. І встановив священик спостереження за домом Господнім.","І взяв сотників і охоронців і скороходів і весь народ землі, і провели царя з дому Господнього, і прийшли дорогою через ворота охоронців у дім царський; і він сів на престолі царів.","І веселився весь народ землі, і місто заспокоїлося. А Гофолію умертвили мечем у царському домі.","Семи років був Іоас, коли став царем."],"x":{"1":"13.22.10","2":"13.22.11|11.8.19","3":"13.22.12","4":"13.23.3","6":"13.23.4-5|11.15.35","7":"12.9.25|10.2.3","10":"13.23.9","12":"13.23.11|4.17.18|8.10.24","13":"13.23.12","14":"11.23.3|10.8.22|13.23.13","15":"13.23.14","16":"13.23.15","17":"13.23.16","18":"11.10.26|13.23.17","19":"13.23.20","20":"13.23.21"}},{"v":["У сьомий рік Іиуя став царем Іоас і сорок років царював у Єрусалимі. Ім’я матері його Цив’я, з Вирсавії.","І робив Іоас угодне в очах Господніх у всі дні свої, доки наставляв його священик Іодай;","тільки висоти не були знищені; народ ще приносив жертви і куріння на висотах.","І сказав Іоас священикам: усе срібло, що освячується, яке приносять у дім Господній, срібло від подорожніх, срібло, внесене за кожну душу за оцінкою, усе срібло, скільки кому приходить на серце принести в дім Господній,","нехай беруть священики собі, кожен від свого знайомого, і нехай лагодять вони пошкоджене в храмі, скрізь, де знайдеться пошкодження.","Але оскільки до двадцять третього року царя Іоаса священики не лагодили пошкоджень у храмі,","то цар Іоас покликав священика Іодая і священиків і сказав їм: чому ви не лагодите пошкоджень у храмі? Не беріть же віднині срібла у знайомих своїх, а на полагодження пошкоджень у храмі віддайте його.","І погодилися священики не брати срібла у народу на лагодження пошкоджень у храмі.","І взяв священик Іодай один ящик, і зробив отвір у ньому зверху, і поставив його поряд із жертовником з правого боку, де входили в дім Господній. І кидали туди священики, які стояли на сторожі біля порогу, все срібло, що приносилося в дім Господній.","І коли бачили, що багато срібла в ящику, приходили писар царський і первосвященик, і зав’язували в мішки , і перераховували срібло, знайдене в домі Господньому;","і віддавали перераховане срібло в руки виконавцям робіт, приставленим до дому Господнього, а ці витрачали його на теслярів і будівельників, які працювали в домі Господньому,","і на будівничих стін і на каменотесів, також на закупівлю дерев і тесаних каменів, для полагодження пошкоджень у домі Господньому, і на усе, що витрачалося для підтримки храму.","Але не зроблено було для дому Господнього срібних блюд, ножів, чаш для окроплення , труб, усяких сосудів золотих і сосудів срібних із срібла, що приносили в дім Господній,","а виконавцям робіт віддавали його, і лагодили за нього дім Господній.","І не вимагали звіту від тих людей, яким доручали срібло для роздачі виконавцям робіт, бо вони діяли чесно.","Срібло на жертву за провину і срібло на жертву за гріх не вносилося в дім Господній: воно священикам належало.","Тоді виступив у похід Азаїл, цар Сирійський, і пішов війною на Геф, і взяв його; і мав намір Азаїл іти на Єрусалим.","Але Іоас, цар Юдейський, узяв усе пожертвуване, що пожертвували храму Іосафат, й Іорам і Охозія, батьки його, царі юдейські, і що він сам пожертвував, і все золото, знайдене в скарбницях дому Господнього і дому царського, і послав Азаїлу, царю Сирійському; і він відступив від Єрусалима.","Інше про Іоаса і про все, що він зробив, написано в літописі царів юдейських.","І повстали слуги його, і вчинили змову, й убили Іоаса в домі Милло, на дорозі до Силли.","Його убили слуги його: Іозакар, син Шимеати, та Ієгозавад, син Шомери; і він помер, і поховали його з батьками його в місті Давидовому. І став царем Амасія, син його, замість нього."],"x":{"1":"13.24.1","2":"11.14.3","3":"10.15.14","4":"1.25.2|1.30.13","5":"13.24.5","7":"13.24.5","9":"13.24.8","10":"13.24.11","11":"11.22.4|13.24.12-13","13":"10.7.50|13.24.14","15":"11.22.7","16":"2.5.15","17":"11.8.12","18":"10.15.18|11.16.8|13.24.23","19":"10.14.19","20":"13.24.25","21":"13.24.27"}},{"v":["У двадцять третій рік Іоаса, сина Охозії, царя Юдейського, став царем Іоахаз, син Іиуя, над Ізраїлем у Самарії, і царював сімнадцять років,","і робив неугодне в очах Господніх, і ходив у гріхах Ієровоама, сина Наватового, який увів Ізраїля в гріх, і не відставав від них.","І запалав гнів Господа на Ізраїля, і Він віддавав їх у руку Азаїла, царя Сирійського, і в руку Венадада, сина Азаїлового, в усі дні.","І помолився Іоахаз лицю Господньому, і почув його Господь, тому що бачив утиснення ізраїльтян, як тіснив їх цар Сирійський.","І дав Господь ізраїльтянам визволителя, і вийшли вони з-під руки сиріян, і жили сини Ізраїлеві в наметах своїх, як вчора і третього дня.","Однак же не відступали від гріхів дому Ієровоамового, який ввів Ізраїля в гріх; ходили в них, і діброва стояла в Самарії.","В Іоахаза залишалося війська тільки п’ятдесят вершників, десять колісниць і десять тисяч піших, тому що знищив їх цар Сирійський і перетворив їх на порох на потоптання.","Інше про Іоахаза і про все, що він зробив, і про мужні подвиги його, написано в літописі царів ізраїльських.","І спочив Іоахаз з батьками своїми, і поховали його в Самарії. І став царем Іоас, син його, замість нього.","В тридцять сьомий рік Іоаса, царя Юдейського, став царем Іоас, син Іоахазів, над Ізраїлем у Самарії, і царював шістнадцять років,","і робив неугодне в очах Господніх; не відставав від усіх гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх, але ходив у них.","Інше про Іоаса і про все, що він зробив, і про мужні подвиги його, як він воював з Амасією, царем Юдейським, написано в літописі царів ізраїльських.","І спочив Іоас з батьками своїми, а Ієровоам сів на престолі його. І похований Іоас у Самарії з царями ізраїльськими.","Єлисей занедужав на хворобу, від якої потім і помер. І прийшов до нього Іоас, цар Ізраїльський, і плакав над ним, і говорив: батьку мій! батьку мій! колісниця Ізраїля і кіннота його!","І сказав йому Єлисей: візьми лук і стріли. І взяв він лук і стріли.","І сказав цареві Ізраїльському: поклади руку твою на лук. І поклав він руку свою. І наклав Єлисей руки свої на руки царя,","і сказав: відчини вікно на схід. І він відчинив. І сказав Єлисей: вистріли. І він вистрілив. І сказав: ця стріла визволення від Господа і стріла визволення проти Сирії, і ти вразиш сиріян в Афеку дощенту.","І сказав [Єлисей]: візьми стріли. І він узяв. І сказав цареві Ізраїльському: бий по землі. І ударив він тричі, і зупинився.","І розгнівався на нього чоловік Божий, і сказав: потрібно було б бити п’ять або шість разів, тоді ти побив би сиріян зовсім, а тепер тільки тричі вразиш сиріян.","І помер Єлисей, і поховали його. І полчища моавитян прийшли в землю в наступному році.","І було, що коли ховали одного чоловіка, то, побачивши це полчище, ті, що ховали , кинули того чоловіка в гріб Єлисеїв; і він при падінні своєму торкнувся кісток Єлисея, і ожив, і встав на ноги свої.","Азаїл, цар Сирійський, тіснив ізраїльтян в усі дні Іоахаза.","Але Господь змилосердився над ними, і помилував їх, і повернувся до них заради завіту Свого з Авраамом, Ісааком і Яковом, і не хотів знищити їх, і не відкинув їх від лиця Свого донині.","І вмер Азаїл, цар Сирійський, і став царем Венадад, син його, замість нього.","І взяв назад Іоас, син Іоахаза, з руки Венадада, сина Азаїла, міста, які він узяв війною з руки батька його Іоахаза. Три рази розбив його Іоас і повернув міста Ізраїлеві."],"x":{"2":"11.10.29","3":"10.19.15:17|11.8.12|40.1.4","5":"11.14.17","7":"11.8.12|13.24.23","11":"11.13.2","12":"13.25.17|11.14.8","13":"11.14.16","14":"11.2.12","21":"30.48.14","23":"0.17.7|1.2.24|2.26.42"}},{"v":["На другий рік Іоаса, сина Іоахазового, царя Ізраїльського, став царем Амасія, син Іоаса, цар Юдейський:","двадцяти п’яти років був він, коли став царем, і двадцять дев’ять років царював у Єрусалимі. Ім’я матері його Ієгоаддань, з Єрусалима.","І чинив він угодне в очах Господніх, утім, не так, як батько його Давид: він в усьому чинив так, як батько його Іоас.","Тільки висоти не були знищені: народ приносив ще жертви і куріння на висотах.","Коли утвердилося царство в руках його, тоді він умертвив слуг своїх, які убили царя, батька його.","Але дітей убивць не умертвив, оскільки написано в книзі закону Мойсеєвого, в якій заповів Господь, говорячи: «не повинні бути карані смертю батьки за дітей, і діти не повинні бути карані смертю за батьків, але кожен за свій злочин повинен бути караний смертю».","Він уразив десять тисяч ідумеян у долині Соляній, і взяв Селу війною, і дав їй ім’я Іокфеїл, яке залишається і до цього дня.","Тоді послав Амасія послів до Іоаса, царя Ізраїльського, сина Іоахаза, сина Іиуєвого, сказати: вийди, побачимось особисто.","І послав Іоас, цар Ізраїльський, до Амасії, царя Юдейського, сказати: терен, що на Ливані, послав до кедра, що на Ливані ж, сказати: «віддай дочку свою за дружину синові моєму». Але пройшли дикі звірі, що на Ливані, і стоптали цей терен.","Ти вразив ідумеян, і загордувало серце твоє. Величайся і сиди у себе вдома. Для чого тобі затівати сварку на свою біду? Впадеш ти й Іуда з тобою.","Але не послухався Амасія. І виступив Іоас, цар Ізраїльський, і побачилися особисто він і Амасія, цар Юдейський, у Вефсамисі, що в Юдеї.","І розбиті були юдеї ізраїльтянами, і розбіглися по наметах своїх.","І Амасію, царя Юдейського, сина Іоаса, сина Охозіїного, захопив Іоас, цар Ізраїльський, у Вефсамисі, і пішов у Єрусалим і зруйнував стіну єрусалимську від воріт Єфремових до воріт вугільних на чотириста ліктів.","І взяв усе золото і срібло, і всі сосуди, які знайшлися в домі Господньому й у скарбницях царського дому, і заручників, і повернувся в Самарію.","Інше про Іоаса, що він зробив, і про мужні подвиги його, і як він воював з Амасією, царем Юдейським, написано в літописі царів ізраїльських.","І спочив Іоас з батьками своїми, і похований у Самарії з царями ізраїльськими. І став царем Ієровоам, син його, замість нього.","І жив Амасія, син Іоаса, цар Юдейський, після смерти Іоаса, сина Іоахазового, царя Ізраїльського, п’ятнадцять років.","Інші діла Амасії записані в літописі царів юдейських.","І склали проти нього змову в Єрусалимі, і втік він у Лахис. І послали за ним у Лахис, і умертвили його там.","І привезли його на конях, і він був похований у Єрусалимі з батьками своїми в місті Давидовому.","І взяв весь народ юдейський Азарію, якому було шістнадцять років, і поставили його царем замість батька його Амасії.","Він збудував Елаф, і повернув його Іуді, після того як цар спочив з батьками своїми.","У п’ятнадцятий рік Амасії, сина Іоасового, царя Юдейського, став царем Ієровоам, син Іоасів, цар Ізраїльський, у Самарії, і царював сорок один рік,","і робив він неугодне в очах Господніх: не відступав від усіх гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх.","Він відновив межі Ізраїля, від входу в Емаф до моря пустелі, за словом Господа Бога Ізраїлевого, яке Він прорік через раба Свого Іону, сина Амафіїного, пророка з Гафхефера,","бо Господь бачив біди Ізраїля, дуже гіркі, так що не залишалося ні ув’язненого, ні того, хто залишився, і не було помічника в Ізраїля.","І не зволив Господь викорінити ім’я ізраїльтян з піднебесної, і врятував їх рукою Ієровоама, сина Іоасового.","Інше про Ієровоама і про все, що він зробив, і про мужні подвиги його, як він воював і як повернув Ізраїлю Дамаск і Емаф, що належав Іуді, написано в літописі царів ізраїльських.","І спочив Ієровоам з батьками своїми, з царями ізраїльськими. І став царем Захарія, син його, замість нього."],"x":{"2":"13.25.1","4":"10.3.2|11.12.3","6":"4.24.16|13.25.4|36.18.20","7":"13.25.11","8":"11.13.12|13.25.17","9":"6.9.14|13.25.18","11":"13.25.20","12":"13.25.22","13":"48.14.10","14":"13.25.24","15":"13.25.26","16":"11.13.13","17":"13.25.25","18":"13.25.26","19":"10.15.27|11.12.20","20":"13.25.28","21":"11.15.1-2|13.26.1","22":"4.2.8|13.26.2","23":"38.1.1|40.1.1|40.7.9","24":"10.15.26|11.13.2","25":"3.34.3:8|42.1.1","26":"11.13.4|4.32.36","28":"13.12.15","29":"11.15.8"}},{"v":["У двадцять сьомий рік Ієровоама, царя Ізраїльського, став царем Азарія, син Амасії, цар Юдейський:","він був шістнадцяти років, коли став царем, і п’ятдесят два роки царював у Єрусалимі. Ім’я матері його Ієхолія, з Єрусалима.","Він чинив угодне в очах Господніх у всьому так, як чинив, Амасія, батько його.","Тільки висоти не були знищені: народ приносив ще жертви і куріння на висотах.","І вразив Господь царя, і був він прокаженим до дня смерти своєї і жив у окремому домі. А Іофам, син царя, був начальником над палацом і управляв народом землі.","Інше про Азарію і про все, що він зробив, написано в літописі царів юдейських.","І спочив Азарія з батьками своїми, і поховали його з батьками його в місті Давидовому. І став царем Іофам, син його, замість нього.","У тридцять восьмий рік Азарії, царя Юдейського, став царем Захарія, син Ієровоама, над Ізраїлем у Самарії і царював шість місяців.","Він робив неугодне в очах Господніх, як робили батьки його: не відставав від гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх.","І склав проти нього змову Селлум, син Іависа, і вразив його перед народом і убив його, і став царем замість нього.","Інше про Захарію написано в літописі царів ізраїльських.","Таке було слово Господа, яке він прорік Іиую, сказавши: сини твої до четвертого роду будуть сидіти на престолі Ізраїля. І збулося так.","Селлум, син Іависа, став царем у тридцять дев’ятий рік Азарії, царя Юдейського, і царював один місяць у Самарії.","І пішов Менаїм, син Гадія з Фирци, і прийшов у Самарію, і вразив Селлума, сина Іависового, у Самарії й умертвив його, і став царем замість нього.","Інше про Селлума і про змову його, яку він учинив, написано в літописі царів ізраїльських.","І вразив Менаїм Типсах і всіх, які були в ньому й у межах його, починаючи від Фирци, за те, що місто не відчинило воріт , і розбив його , і всіх вагітних жінок у ньому розрубав.","У тридцять дев’ятому році Азарії, царя Юдейського, став царем Менаїм, син Гадія, над Ізраїлем і царював десять років у Самарії;","і робив він неугодне в очах Господніх; не відставав від гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх, в усі дні свої.","Тоді прийшов Фул, цар Ассирійський, на землю [Ізраїлеву]. І дав Менаїм Фулу тисячу талантів срібла, щоб руки його були за нього і щоб утвердити царство у руках своїх.","І розклав Менаїм це срібло на ізраїльтян, на всіх людей багатих, по п’ятдесят сиклів срібла на кожну людину, щоб віддати цареві Ассирійському. І пішов назад цар Ассирійський і не залишився там у землі.","Інше про Менаїма і про все, що він зробив, написано в літописі царів ізраїльських.","І спочив Менаїм з батьками своїми. І став царем Факія, син його, замість нього.","У п’ятдесятий рік Азарії, царя Юдейського, став царем Факія, син Менаїма, над Ізраїлем у Самарії і царював два роки;","і робив він неугодне в очах Господніх; не відставав від гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх.","І склав проти нього змову Факей, син Ремалії, сановник його, і вразив його в Самарії в палаті царського дому, з Арговом і Арієм, маючи із собою п’ятдесят чоловік галаадитян, і умертвив його, і став царем замість нього.","Інше про Факію і про все, що він зробив, написано в літописі царів ізраїльських.","У п’ятдесят другий рік Азарії, царя Юдейського, став царем Факей, син Ремалії, над Ізраїлем у Самарії і царював двадцять років;","і робив він неугодне в очах Господніх: не відступав від гріхів Ієровоама, сина Наватового, який увів Ізраїля в гріх.","У дні Факея, царя Ізраїльського, прийшов Феглаффелласар, цар Ассирійський, і взяв Іон, Авел-Беф-Мааху, й Іанох, і Кедес, і Асор, і Галаад, і Галилею, всю землю Неффалимову, і переселив їх в Ассирію.","І склав змову Осія, син Или, проти Факея, сина Ремаліїного, і вразив його, і умертвив його, і став царем замість нього в двадцятий рік Іоафама, сина Озиїного.","Інше про Факея і про все, що він зробив, написано в літописі царів ізраїльських.","У другий рік Факея, сина Ремаліїного, царя Ізраїльського, став царем Іоафам, син Озії, царя Юдейського.","Двадцяти п’яти років був він, коли став царем, і шістнадцять років царював у Єрусалимі. Ім’я матері його Ієруша, дочка Садока.","Він робив угодне в очах Господніх: в усьому, як чинив Озія, батько його, так чинив і він.","Тільки висоти не були знищені: народ приносив ще жертви і куріння на висотах. Він побудував верхні ворота при домі Господньому.","Інше про Іоафама і про все, що він зробив, написано в літописі царів юдейських.","У ті дні почав Господь посилати на Юдею Рецина, царя Сирійського, і Факея, сина Ремаліїного.","І спочив Іоафам з батьками своїми, і похований з батьками своїми в місті Давида, батька його. І став царем Ахаз, син його, замість нього."],"x":{"1":"11.14.21|13.26.1","2":"11.14.21","3":"11.14.3|13.26.4","4":"10.22.43","5":"2.13.46|13.26.21","6":"13.26.1:17","7":"13.26.23","8":"11.14.29","9":"11.10.29","10":"13.28.12|40.7.9","12":"11.10.30","14":"10.16.8:17","18":"11.13.2","19":"12.5.26|32.50.17|36.23.5","20":"11.23.35|13.24.6","24":"11.10.29","25":"10.16.9|11.14.19","28":"10.14.16","29":"12.5.26","30":"11.12.20","31":"13.28.6","32":"43.1.1","33":"13.27.1","35":"10.15.14|13.27.2","36":"13.27.1","37":"11.16.5|31.7.1","38":"9.5.7:9|13.27.9"}},{"v":["У сімнадцятий рік Факея, сина Ремаліїного, став царем Ахаз, син Іоафама, царя Юдейського.","Двадцяти років був Ахаз, коли став царем, і шістнадцять років царював у Єрусалимі, і не робив угодного в очах Господа Бога свого, як Давид, батько його,","але ходив шляхом царів ізраїльських, і навіть сина свого провів через вогонь, наслідуючи мерзоти народів, яких прогнав Господь від лиця синів Ізраїлевих,","і звершував жертви і куріння на висотах і на пагорбах і під усяким тінистим деревом.","Тоді пішов Рецин, цар Сирійський, і Факей, син Ремаліїн, цар Ізраїльський, проти Єрусалима, щоб завоювати його, і тримали Ахаза в облозі, але подолати не могли.","У той час Рецин, цар Сирійський, повернув Сирії Елаф і вигнав юдеїв з Елафа; ідумеяни вступили в Елаф, і живуть там до цього дня.","І послав Ахаз послів до Феглаффелласара, царя Ассирійського, сказати: раб твій і син твій я; прийди і захисти мене від руки царя Сирійського і від руки царя Ізраїльського, які повстали на мене.","І взяв Ахаз срібло і золото, яке знайшлося в домі Господньому й у скарбницях дому царського, і послав цареві Ассирійському в дарунок.","І послухав його цар Ассирійський; і пішов цар Ассирійський у Дамаск, і взяв його, і переселив жителів його в Кир, а Рецина умертвив.","І пішов цар Ахаз назустріч Феглаффелласару, царю Ассирійському, у Дамаск, і побачив жертовник, що у Дамаску, і послав цар Ахаз до Урії священика зображення жертовника і креслення всього облаштування його.","І побудував священик Урія жертовник за зразком, який надіслав цар Ахаз з Дамаска; і зробив так священик Урія до прибуття царя Ахаза з Дамаска.","І прийшов цар з Дамаска, і побачив цар жертовник, і підійшов цар до жертовника, і приніс на ньому жертву;","і спалив всепалення своє і хлібне приношення, і зробив зливання своє, і окропив кров’ю мирної жертви свій жертовник.","А мідний жертовник, що перед лицем Господнім, він пересунув від лицевої сторони храму, з місця між жертовником новим і домом Господнім, і поставив його збоку від цього жертовника на північ.","І дав наказ цар Ахаз священикові Урії, сказавши: на великому жертовнику спалюй ранкове всепалення і вечірнє хлібне приношення, і всепалення від царя і хлібне приношення від нього, і всепалення від усіх людей землі і хлібне приношення від них, і узливання від них, і всякою кров’ю всепалень і всякою кров’ю жертв окроплюй його, а жертовник мідний залишиться на мій розсуд.","І зробив священик Урія все так, як наказав цар Ахаз.","І обламав цар Ахаз обідки на підставах, і зняв з них умивальниці, і море зняв з мідних волів, що були під ним, і поставив його на кам’яну підлогу.","І скасував критий суботній хід, який побудували при храмі, і зовнішній царський вхід до дому Господнього, заради царя Ассирійського.","Інше про Ахаза, що він зробив, написано в літописі царів юдейських.","І спочив Ахаз з батьками своїми, і похований з батьками своїми в місті Давидовому. І став царем Єзекія, син його, замість нього."],"x":{"2":"13.28.1","3":"11.8.18|13.28.2|2.18.21","5":"31.7.1","6":"11.14.22","7":"13.28.16|38.7.11|32.50.17","8":"10.15.18|11.12.18|31.7.20","10":"13.28.23","14":"13.4.1","17":"10.7.23:28","18":"13.28.24","19":"13.28.1-2","20":"13.28.27|31.14.28"}},{"v":["У дванадцятий рік Ахаза, царя Юдейського, став царем Осія, син Или, у Самарії над Ізраїлем і царював дев’ять років.","І робив він неугодне в очах Господніх, але не так, як царі ізраїльські, які були раніше нього.","Проти нього виступив Салманассар, цар Ассирійський, і зробився Осія підвладним йому і давав йому данину.","І помітив цар Ассирійський в Осії зраду, тому що він посилав послів до Сигора, царя Єгипетського, і не доставляв данину цареві Ассирійському щороку; і взяв його цар Ассирійський під варту, і закрив його у в’язниці.","І пішов цар Ассирійський на всю землю, і підійшов до Самарії, і тримав її в облозі три роки.","В дев’ятий рік Осії взяв цар Ассирійський Самарію, і переселив ізраїльтян в Ассирію, і оселив їх у Халаху й у Хаворі, біля річки Гозан, і в містах мідійських.","Коли стали грішити сини Ізраїлеві перед Господом Богом своїм, Який вивів їх із землі Єгипетської, з-під руки фараона, царя Єгипетського, і стали шанувати богів інших,","і стали чинити за звичаями народів, яких прогнав Господь від лиця синів Ізраїлевих, і за звичаями царів ізраїльських, як чинили вони;","і стали робити сини Ізраїлеві діла неугодні Господу Богу своєму, і спорудили собі висоти в усіх містах своїх, починаючи від сторожової вежі до укріпленого міста,","і поставили у себе статуї і зображення Астарт на усякому високому пагорбі й під усяким тінистим деревом,","і стали там звершувати куріння на усіх висотах, подібно до народів, яких вигнав від них Господь, і робили лихі справи, які прогнівляли Господа,","і служили ідолам, про яких говорив їм Господь: «не робіть цього»;","тоді Господь через усіх пророків Своїх, через усякого прозорливця застерігав Ізраїля й Іуду, говорячи: поверніться з ваших злих доріг і додержуйтеся заповідей Моїх, уставів Моїх, згідно з усім вченням, яке Я заповів батькам вашим і яке Я дав вам через рабів Моїх, пророків.","Але вони не слухали і зробили жорсткою шию свою, як була шия батьків їхніх, які не вірували в Господа, Бога свого;","і нехтували устави Його, і завіт Його, який Він уклав з батьками їхніми, і одкровення Його, якими Він застерігав їх, і пішли вслід марнотам й змарнотились, і вслід народам навколишнім, про які Господь заповів їм, щоб не робили так, як вони,","і залишили всі заповіді Господа Бога свого, і зробили собі відлиті зображення двох тельців, і влаштували діброву, і поклонялися усьому воїнству небесному, і служили Ваалу,","і проводили синів своїх і дочок своїх через вогонь, і ворожили, і чародіяли, і віддалися тому, щоб робити неугодне в очах Господа і прогнівляти Його.","І прогнівався Господь сильно на ізраїльтян, і відкинув їх від лиця Свого. Не залишилося нікого, крім одного коліна Іудиного.","І Іуда також не дотримувався заповідей Господа Бога свого, і чинив за звичаями ізраїльтян, як чинили вони.","І відвернувся Господь від усіх нащадків Ізраїля, й упокорив їх, і віддавав їх у руки грабіжників, і нарешті відкинув їх від лиця Свого.","Ізраїльтяни відокремилися від дому Давида і поставили царем Ієровоама, сина Наватового; і відвернув Ієровоам ізраїльтян від Господа, і втягнув їх у великий гріх.","І чинили сини Ізраїлеві за всіма гріхами Ієровоама, які він робив, не відступали від них,","доки Господь не відкинув Ізраїля від лиця Свого, як говорив через усіх рабів Своїх, пророків. І переселений Ізраїль із землі своєї в Ассирію, де він і до цього дня.","І переселив цар Ассирійський людей з Вавилона, і з Кути, і з Авви, і з Емафа, і з Сепарваїма, і оселив їх у містах самарійських замість синів Ізраїлевих. І вони оволоділи Самарією, і стали жити в містах її.","І оскільки на початку проживання свого там вони не шанували Господа, то Господь посилав на них левів, які умертвляли їх.","І донесли цареві Ассирійському, і сказали: народи, яких ти переселив і оселив у містах самарійських, не знають закону Бога тієї землі, і за те Він посилає на них львів, і ось вони умертвляють їх, тому що вони не знають закону Бога тієї землі.","І повелів цар Ассирійський, і сказав: відправте туди одного зі священиків, яких ви виселили звідти; нехай піде і живе там, і він навчить їх закону Бога тієї землі.","І прийшов один зі священиків, яких виселили із Самарії, і жив у Вефилі, й учив їх, як шанувати Господа.","Притому зробив кожен народ і своїх богів і поставив у капищах висот, які спорудили самаряни, — кожен народ у своїх містах, де живуть вони.","Вавилоняни зробили Суккот-Беноф, кутийці зробили Нергала, емафяни зробили Ашиму,","аввийці зробили Нивхаза і Тартака, а сепарваїмці спалювали синів своїх у вогні Адрамелеху й Анамелеху, богам сепарваїмським.","Тим часом шанували і Господа, і зробили у себе священиків висот зі свого середовища, і вони служили у них у капищах висот.","Господа вони шанували, і богам своїм вони служили за звичаєм народів, з яких виселили їх.","До сьогодні чинять вони за попередніми своїми звичаями: не бояться Господа і не роблять за уставами і за обрядами, і за законом і за заповідями, які заповів Господь синам Якова, якому дав Він ім’я Ізраїля.","Уклав Господь з ними завіт і заповів їм, говорячи: не шануйте богів інших, і не поклоняйтеся їм, і не служіть їм, і не приносьте жертв їм,","але Господа, Який вивів вас із землі Єгипетської силою великою і м’язами простертими, — Його шануйте і Йому поклоняйтеся, і Йому приносьте жертви,","і устави, й повеління, і закон, і заповіді, які Він написав вам, намагайтеся виконувати в усі дні, і не шануйте богів інших;","і завіту, який Я уклав з вами, не забувайте, і не шануйте богів інших,","тільки Господа Бога вашого шануйте, і Він визволить вас від руки усіх ворогів ваших.","Але вони не послухали, а чинили за попередніми своїми звичаями.","Народи ці шанували Господа, але й ідолам своїм служили. Та й діти їхні і діти дітей їхніх до цього дня чинять так само, як робили батьки їхні."],"x":{"1":"11.15.30","3":"31.36.1|32.50.17|38.10.6","4":"38.7.12","5":"11.18.10","6":"11.18.10","8":"2.18.3|11.16.3|38.7.8","9":"25.35.3|31.5.20","10":"2.26.1","12":"1.20.4:23|1.23.13|4.5.7","13":"32.25.5","14":"1.32.9|4.31.27","15":"62.1.21|2.18.24","16":"1.32.8|4.4.19|10.16.31","17":"2.18.21|4.18.10|38.13.2","18":"11.23.27|32.7.15|10.11.32","21":"10.12.16","22":"10.12.30|11.13.2","23":"32.25.4","24":"14.4.10","25":"2.26.22","28":"14.4.2","29":"42.1.5|62.1.23","31":"31.36.19","33":"53.4.20|52.11.23|63.10.21","34":"36.20.18|0.32.28|10.18.31","35":"1.20.2-3|1.23.13|6.6.10","36":"1.6.6","37":"0.26.5","41":"14.4.3|53.4.22"}},{"v":["У третій рік Осії, сина Или, царя Ізраїльського, став царем Єзекія, син Ахаза, царя Юдейського.","Двадцяти п’яти років був він, коли став царем, і двадцять дев’ять років царював у Єрусалимі; ім’я матері його Аві, дочка Захарії.","І робив він угодне в очах Господа в усьому так, як робив Давид, батько його;","він знищив висоти, розбив статуї, вирубав діброву і знищив мідного змія, якого зробив Мойсей, тому що до самих тих днів сини Ізраїлеві кадили йому і називали його Нехуштан.","На Господа Бога Ізраїлевого уповав він; і такого, як він, не було між усіма царями Юдейськими і після нього і раніше нього.","І приліпився він до Господа і не відступав від Нього, і дотримувався заповідей Його, які заповів Господь Мойсеєві.","І був Господь з ним: скрізь, куди б він не ходив, чинив він розсудливо. І відійшов він від царя Ассирійського, і не став служити йому.","Він уразив филистимлян до Гази й у межах її, від сторожової вежі до укріпленого міста.","У четвертий рік царя Єзекії, тобто в сьомий рік Осії, сина Или, царя Ізраїльського, пішов Салманассар, цар Ассирійський, на Самарію і обложив її,","і взяв її через три роки; у шостий рік Єзекії, тобто в дев’ятий рік Осії, царя Ізраїльського, взято Самарію.","І переселив цар Ассирійський ізраїльтян в Ассирію, і оселив їх у Халаху й у Хаворі, біля ріки Гозан, і в містах мідійських,","за те, що вони не слухали голосу Господа Бога свого і переступили завіт Його, усе, що заповів Мойсей раб Господній, вони і не слухали і не виконували.","У чотирнадцятий рік царя Єзекії пішов Сеннахирим, цар Ассирійський, проти всіх укріплених міст Іуди і взяв їх.","І послав Єзекія, цар Юдейський, до царя Ассирійського в Лахис сказати: винен я; відійди від мене; що накладеш на мене, я внесу. І наклав цар Ассирійський на Єзекію, царя Юдейського, триста талантів срібла і тридцять талантів золота.","І віддав Єзекія все срібло, яке знайшлося в домі Господньому і в скарбницях дому царського.","У той час зняв Єзекія золото з дверей дому Господнього і з дверних стовпів, які позолотив Єзекія, цар Юдейський, і віддав його цареві Ассирійському.","І послав цар Ассирійський Тартана і Рабсариса і Рабсака з Лахиса до царя Єзекії з великим військом у Єрусалим. І пішли, і прийшли до Єрусалима; і пішли, і прийшли, і стали біля водопроводу верхнього ставу, що на дорозі поля білильного.","І кликали вони царя. І вийшов до них Єлиаким, син Хелкиїн, начальник палацу, і Севна писар, і Іоах, син Асафів.","І сказав їм Рабсак: скажіть Єзекії: так говорить цар великий, цар Ассирійський: що це за уповання, на яке ти сподіваєшся?","Ти говорив тільки пусті слова: для війни потрібні порада і сила. Нині ж на кого ти уповаєш, що відокремився від мене?","Ось, ти думаєш опертися на Єгипет, на цю тростину надламану, яка, якщо хто обіпреться на неї, увійде йому в руку і проколе її. Такий фараон, цар Єгипетський, для всіх, хто уповає на нього.","А якщо ви скажете мені: «на Господа Бога нашого ми уповаємо», то чи на того, якого висоти і жертовники знищив Єзекія, і сказав Іуді та Єрусалиму: «перед цим тільки жертовником поклоняйтеся в Єрусалимі»?","Отже, вступи в союз з господарем моїм царем Ассирійським: я дам тобі дві тисячі коней, чи можеш дістати собі вершників для них?","Як тобі подолати й одного вождя з найменших слуг господаря мого? І уповаєш на Єгипет заради колісниць і коней?","Притому ж хіба я без волі Господньої пішов на місце це, щоб зруйнувати його? Господь сказав мені: «піди на землю цю і розори її».","І сказав Єлиаким, син Хелкиїн, і Севна й Іоах Рабсаку: говори рабам твоїм арамейською, тому що розуміємо ми, а не говори з нами юдейською, щоб не розумів народ, що на стіні.","І сказав їм Рабсак: хіба тільки до господаря твого і до тебе послав мене господар мій сказати ці слова? Ні, також і до людей, які сидять на стіні, щоб їсти кал свій і пити сечу свою з вами.","І встав Рабсак і виголосив гучним голосом юдейською, і говорив, і сказав: слухайте слово царя великого, царя Ассирійського!","Так говорить цар: нехай не зваблює вас Єзекія, тому що він не може вас врятувати від руки моєї;","і нехай не обнадіює вас Єзекія Господом, говорячи: «врятує нас Господь і не буде місто це віддане в руки царя Ассирійського».","Не слухайте Єзекії. Тому що так говорить цар Ассирійський: примиріться зі мною і вийдіть до мене, і нехай кожен їсть плоди виноградної лози своєї і смоковниці своєї, і нехай кожен п’є воду зі свого колодязя,","поки я не прийду і не візьму вас у землю таку саму, як і ваша земля, у землю хліба і вина, у землю плодів і виноградників, у землю оливкових дерев і меду, і будете жити, і не помрете. Не слухайте ж Єзекії, який зваблює вас, говорячи: «Господь врятує нас».","Чи врятували боги народів, кожен свою землю, від руки царя Ассирійського?","Де боги Емафа й Арпада? Де боги Сепарваїма, Ени та Івви? Чи врятували вони Самарію від руки моєї?","Хто з усіх богів земель цих урятував землю свою від руки моєї? Так невже Господь врятує Єрусалим від руки моєї?","І мовчав народ і не відповідали йому ні слова, тому що був наказ царя: «не відповідайте йому».","І прийшов Єлиаким, син Хелкиїн, начальник палацу, і Севна писар і Іоах, син Асафів, діловод, до Єзекії в розідраному одягу, і переказали йому слова Рабсакові."],"x":{"1":"13.28.27","2":"13.29.1","4":"3.21.9","5":"26.3.5|31.33.6","6":"4.17.11","7":"26.16.20|31.36.7","8":"31.14.29","9":"11.17.5-6","11":"11.17.6","13":"13.32.1|31.36.1|30.48.20","14":"43.1.13","15":"10.15.18|11.12.18","17":"13.32.9|31.20.1|31.36.2","18":"11.19.2|31.22.20","19":"13.32.10","21":"31.20.5|31.36.6|36.29.6","22":"13.32.11|1.20.24|4.12.5","24":"31.36.9","26":"31.22.20|13.32.18","27":"11.6.25","29":"11.19.10|13.32.11|31.36.14","31":"10.4.25","33":"13.32.13|31.36.18","35":"37.3.15|13.32.14","36":"31.36.21","37":"31.22.20|0.37.29"}},{"v":["Коли почув це цар Єзекія, то роздер одяг свій і покрився веретищем, і пішов у дім Господній.","І послав Єлиакима, начальника палацу, і Севну писаря, і старших священиків, покритих веретищем, до Ісаї пророка, сина Амосового.","І вони сказали йому: так говорить Єзекія: день скорботи і покарання і посоромлення — день цей; тому що дійшли немовлята до отвору утроби материнської, а сили немає народити.","Може, почує Господь Бог твій усі слова Рабсака, якого послав цар Ассирійський, господар його, хулити Бога живого і ганьбити словами, які чув Господь Бог твій. Принеси ж молитву за тих, що залишилися, які перебувають ще живими.","І прийшли слуги царя Єзекії до Ісаї,","і сказав їм Ісая: так скажіть господарю вашому: так говорить Господь: не бійся слів, які ти чув, якими ганьбили Мене слуги царя Ассирійського.","Ось Я пошлю в нього дух, і він почує вістку, і повернеться в землю свою, і Я вражу його мечем на землі його.","І повернувся Рабсак, і знайшов царя Ассирійського, який воював проти Ливни, тому що він чув, що той відійшов від Лахиса.","І почув він про Тиргака, царя Ефіопського; йому сказали: ось, він вийшов воювати з тобою. І знову послав він послів до Єзекії сказати:","так скажіть Єзекії, царю Юдейському: нехай не обманює тебе Бог твій, на Якого ти уповаєш, думаючи: «не буде відданий Єрусалим до рук царя Ассирійського».","Адже ти чув, що зробили царі ассирійські з усіма землями, наклавши на них закляття, — і чи ти уцілієш?","Боги народів, яких розорили батьки мої, чи врятували їх? Чи врятували Гозан, і Харан, і Рецеф, і синів Едена, що у Фалассарі?","Де цар Емафа, і цар Арпада, і цар міста Сепарваїма, Ени та Івви?","І взяв Єзекія лист із руки послів, і прочитав його, і пішов у дім Господній, і розгорнув його Єзекія перед лицем Господнім,","і молився Єзекія перед лицем Господнім і говорив: Господи Боже Ізраїлів, що сидиш на херувимах! Ти один Бог усіх царств земних, Ти створив небо і землю.","Прихили, Господи, вухо Твоє і почуй [мене]; відкрий, Господи, очі Твої і подивись, і почуй слова Сеннахирима, який послав ганьбити [Тебе,] Бога живого!","Правда, о, Господи, царі ассирійські розорили народи і землі їхні,","і покидали богів їхніх у вогонь; але це не боги, а творіння рук людських, дерево і камінь; тому і знищили їх.","І нині, Господи Боже наш, спаси нас від руки його, і дізнаються всі царства землі, що Ти, Господи, Бог єдиний.","І послав Ісая, син Амосів, до Єзекії сказати: так говорить Господь Бог Ізраїлів: те, про що ти молився Мені проти Сеннахирима, царя Ассирійського, Я почув.","Ось слово, яке прорік Господь про нього: знехтує тебе, насміється з тебе незаймана дочка Сиона; услід тобі похитає головою дочка Єрусалима.","Кого ти ганив і ганьбив? І на кого ти підніс голос і підняв так високо око своє? На Святого Ізраїлевого!","Через послів твоїх ти ганив Господа і сказав: «з безліччю колісниць моїх я зійшов на висоту гір, на ребра Ливану, і зрубав великі кедри його, добірні кипариси його, і прийшов на саме крайнє пристановище його, у гай саду його;","і відкопував я, і пив воду чужу, і висушу ступнями ніг моїх усі ріки єгипетські».","Хіба ти не чув, що Я здавна зробив це, у давні дні наперед накреслив це, а нині виконав тим, що ти спустошуєш укріплені міста, перетворюючи на купи руїн?","І жителі їх зробилися малопотужні, тремтять і залишаються в соромі. Вони стали як трава на полі і ніжна зелень, як парості на покрівлях і обпалений хліб, раніше ніж виколосився.","Чи сядеш ти, чи вийдеш, чи ввійдеш, Я все знаю; знаю і зухвалість твою проти Мене.","За твою зухвалість проти Мене і за те, що гординя твоя дійшла до вух Моїх, Я вкладу кільце Моє в ніздрі твої і вудила Мої в рот твій, і поверну тебе назад тією ж дорогою, якою прийшов ти.","І ось тобі, [Єзекіє,] знамення: їжте в цей рік те, що виросло від упалого зерна, і в другий рік — самородне, а на третій рік сійте і жніть, і садіть виноградні сади і їжте плоди їх.","І вціліле в домі Іудиному, що залишилося, пустить знову корінь внизу і принесе плід вгорі,","тому що з Єрусалима вийде залишок, і спасенне від гори Сиону. Ревність Господа Саваофа зробить це.","Тому так говорить Господь про царя Ассирійського: «не ввійде він у це місто, і не кине туди стріли, і не приступить до нього з щитом, і не насипле проти нього валу.","Тією ж дорогою, якою прийшов, повернеться, і в місто це не ввійде, говорить Господь.","Я буду охороняти місто це, щоб спасти його заради Себе і заради Давида, раба Мого».","І сталося в ту ніч: пішов ангел Господній і вразив у стані Ассирійському сто вісімдесят п’ять тисяч. І встали зранку, і ось усі тіла мертві.","І вирушив, і пішов, і повернувся Сеннахирим, цар Ассирійський, і жив у Ниневії.","І коли він поклонявся в домі Нисроха, бога свого, то Адрамелех і Шарецер, сини його, убили його мечем, а самі втекли в землю Араратську. І став царем Асардан, син його, замість нього."],"x":{"1":"31.37.1","2":"11.18.18","3":"31.13.8|31.26.18|31.37.3","5":"31.37.6","7":"11.7.6","9":"31.37.9","10":"11.18.30","12":"11.18.33|13.32.19","14":"31.37.14","15":"8.4.4|25.98.1","16":"8.17.10","19":"30.36.5","20":"13.32.20|31.37.21","21":"31.1.8","23":"31.37.24|48.11.2","24":"31.37.25","25":"31.43.13|31.44.7","26":"25.36.2|25.91.8|31.37.27","28":"10.20.28|36.29.4","29":"31.37.30|2.25.3","31":"31.37.32","34":"11.20.6|10.11.13","35":"30.48.24|31.37.36|21.7.41|22.8.19|13.32.21","37":"18.1.21|14.4.2"}},{"v":["У ті дні занедужав Єзекія смертельно, і прийшов до нього Ісая, син Амосів, пророк, і сказав йому: так говорить Господь: зроби заповіт для дому твого, тому що помреш ти і не видужаєш.","І відвернувся [Єзекія] лицем своїм до стіни і молився Господу, говорячи:","«О, Господи! пом’яни, що я ходив перед лицем Твоїм вірно і з відданим Тобі серцем, і робив угодне в очах Твоїх». І заплакав Єзекія сильно.","Ісая ще не вийшов з міста, як було до нього слово Господнє:","повернися і скажи Єзекії, владиці народу Мого: так говорить Господь Бог Давида, батька твого: Я почув молитву твою, побачив сльози твої. Ось, Я зцілю тебе; у третій день підеш у дім Господній;","і додам до днів твоїх п’ятнадцять років, і від руки царя Ассирійського врятую тебе і місто це, і захищу місто це заради Себе і заради Давида, раба Мого.","І сказав Ісая: візьміть пласт смокв. І взяли, і приклали до нариву; і він видужав.","І сказав Єзекія Ісаї: яке знамення, що Господь зцілить мене, і що піду я на третій день у дім Господній?","І сказав Ісая: ось тобі знамення від Господа, що виконає Господь слово, яке Він прорік: чи вперед пройти тіні на десять ступенів, чи повернутися на десять ступенів?","І сказав Єзекія: легко тіні пересунутися вперед на десять ступенів; ні, нехай повернеться тінь назад на десять ступенів.","І воззвав Ісая пророк до Господа, і повернув тінь назад на ступенях, де вона спускалася по ступенях Ахазових, на десять ступенів.","У той час послав Беродах Баладан, син Баладана, цар Вавилонський, листи і подарунок Єзекії, бо він чув, що Єзекія був хворий.","Єзекія, вислухавши посланих, показав їм комори свої, срібло і золото, і пахощі, і мастила дорогі, і весь збройний дім свій і все, що знаходилося в скарбницях його; не залишалося жодної речі, яку б не показав їм Єзекія в домі своєму і в усьому володінні своєму.","І прийшов Ісая пророк до царя Єзекії і сказав йому: що говорили ці люди, і звідки вони приходили до тебе? І сказав Єзекія: із землі далекої вони приходили, з Вавилона.","І сказав Ісая : що вони бачили в домі твоєму? І сказав Єзекія: усе, що в домі моєму, вони бачили, не залишилося жодної речі, яку я не показав би їм у скарбницях моїх.","І сказав Ісая Єзекії: вислухай слово Господнє:","ось прийдуть дні, і взяте буде усе, що в домі твоєму, і що зібрали батьки твої до цього дня, у Вавилон; нічого не залишиться, говорить Господь.","Із синів твоїх, які вийдуть від тебе, яких ти народиш, візьмуть, і будуть вони євнухами в палаці царя Вавилонського.","І сказав Єзекія Ісаї: благе слово Господнє, яке ти прорік. І продовжував: нехай буде мир і добробут у дні мої!","Інше про Єзекію і про всі подвиги його, і про те, що він зробив ставок і водопровід і провів воду в місто, написано в літописі царів юдейських.","І спочив Єзекія з батьками своїми, і став царем Манассія, син його, замість нього."],"x":{"1":"13.32.24|31.38.1","3":"10.2.4","6":"31.38.5|75.11.34|11.19.34","7":"31.38.21","8":"6.6.17","9":"30.48.26","11":"24.9.7","12":"31.39.1","13":"13.32.27","15":"11.20.13","17":"11.24.13|13.32.25|32.52.17","19":"31.39.8|13.32.26","20":"11.18.17|17.3.16|13.29.1"}},{"v":["Дванадцяти років був Манассія, коли став царем, і п’ятдесят років царював у Єрусалимі; ім’я матері його Хефциба.","І робив він неугодне в очах Господніх, наслідуючи мерзоти народів, яких прогнав Господь від лиця синів Ізраїлевих.","І знову спорудив висоти, які знищив батько його Єзекія, і поставив жертовники Ваалу, і зробив діброву, як зробив Ахав, цар Ізраїльський; і поклонявся всьому воїнству небесному, і служив йому.","І спорудив жертовники в домі Господньому, про який сказав Господь: «в Єрусалимі покладу ім’я Моє».","І спорудив жертовники всьому воїнству небесному на обох дворах дому Господнього,","і провів сина свого через вогонь, і чаклував, і ворожив, і завів викликувачів мерців і чаклунів; багато зробив неугодного в очах Господа, щоб прогнівити Його.","І поставив ідола Астарти, якого зробив у домі, про який говорив Господь Давиду і Соломону, синові його: «у домі цьому і в Єрусалимі, який Я обрав із усіх колін Ізраїлевих, Я покладу ім’я Моє повіки;","і не дам надалі виступити нозі ізраїльтянина із землі, яку Я дав батькам їхнім, якщо тільки вони будуть намагатися чинити згідно з усім тим, що Я повелів їм, і з усім законом, який заповів їм раб Мій Мойсей».","Але вони не послухалися; і спокусив їх Манассія до того, що вони чинили гірше за ті народи, які знищив Господь від лиця синів Ізраїлевих.","І говорив Господь через рабів Своїх пророків і сказав:","за те, що зробив Манассія, цар Юдейський, такі мерзоти, гірші за все те, що робили аморреї, які були раніше нього, і ввів Іуду в гріх ідолами своїми,","за те, так говорить Господь, Бог Ізраїлів, ось, Я наведу таке зло на Єрусалим і на Іуду, про яке, якщо хто почує, задзвенить в обох вухах у нього;","і простягну на Єрусалим мірчу вірьовку Самарії і висок дому Ахава, і витру Єрусалим так, як витирають чашу, — витруть і перекинуть її;","і відкину залишок наділу Мого, і віддам їх у руку ворогів їхніх, і будуть на розкрадання і розграбування усім ворогам своїм,","за те, що вони робили неугодне в очах Моїх і прогнівляли Мене з того дня, як вийшли батьки їхні з Єгипту, і до цього дня.","Ще ж пролив Манассія і дуже багато невинної крови, так що наповнив нею Єрусалим від краю до краю, крім свого гріха, що він увів Іуду в гріх — робити неугодне в очах Господніх.","Інше про Манассію і про все, що він зробив, і про гріхи його, в чому він згрішив, написано в літописі царів юдейських.","І спочив Манассія з батьками своїми, і похований у саду біля дому його, в саду Уззи. І став царем Аммон, син його, замість нього.","Двадцяти двох років був Аммон, коли став царем, і два роки царював у Єрусалимі; ім’я матері його Мешуллемеф, дочка Харуца, з Ятби.","І робив він неугодне в очах Господніх так, як робив Манассія, батько його;","і ходив тією ж точно дорогою, якою ходив батько його, і служив ідолам, яким служив батько його, і поклонявся їм,","і залишив Господа Бога батьків своїх, не ходив путями Господніми.","І вчинили змову слуги Аммонові проти нього, й умертвили царя в домі його.","Але народ землі перебив усіх, хто був у змові проти царя Аммона; і поставив народ царем над землею Іосію, сина його, замість нього.","Інше про Аммона, що він зробив, написано в літописі царів юдейських.","І поховали його в гробниці його, в саду Уззи. І став царем Іосія, син його, замість нього."],"x":{"1":"13.33.1","2":"4.18.9|13.28.3","3":"13.33.3","4":"4.12.5:11|9.7.13|10.8.29|32.32.34","6":"2.19.26|4.18.10-11|8.28.9|32.32.35","7":"10.9.3","8":"13.33.8","9":"13.33.9","10":"13.33.18","11":"11.24.3","12":"8.3.11|32.19.3","13":"31.34.11|33.2.8|40.7.9","15":"32.15.4","16":"11.24.4|36.22.4","17":"13.33.18","18":"13.33.20","19":"13.33.21","20":"13.33.22","22":"10.11.33","23":"11.12.20","24":"11.14.5|13.33.25","25":"13.33.21","26":"13.33.25"}},{"v":["Восьми років був Іосія, коли став царем, і тридцять один рік царював у Єрусалимі; ім’я матері його Ієдида, дочка Адаії, з Боцкафи.","І робив він угодне в очах Господніх, і ходив у всьому путями Давида, батька свого, і не ухилявся ні праворуч, ні ліворуч.","У вісімнадцятий рік царя Іосії, послав цар Шафана, сина Ацалії, сина Мешулламового, писаря, у дім Господній, сказавши:","піди до Хелкії первосвященика, нехай він перерахує срібло, принесене в дім Господній, яке зібрали від народу ті, що стояли на сторожі біля порогу,","і нехай віддадуть його в руки виконавцям робіт, приставленим до дому Господнього, а ці нехай роздають його тим, хто працює в домі Господньому, на полагодження пошкоджень дому,","теслям і мулярам, і будівничим стін, і на купівлю дерев і тесаних каменів для лагодження дому;","втім, не вимагати у них звіту в сріблі, переданому в руки їхні, тому що вони чинять чесно.","І сказав Хелкія первосвященик Шафану писарю: книгу закону я знайшов у домі Господньому. І подав Хелкія книгу Шафану, і він читав її.","І прийшов Шафан писар до царя, і приніс цареві відповідь, і сказав: взяли раби твої срібло, знайдене в домі, і передали його в руки виконавцям робіт, приставленим до дому Господнього.","І доніс Шафан писар царю, говорячи: книгу дав мені Хелкія священик. І читав її Шафан перед царем.","Коли почув цар слова книги закону, то роздер одяг свій.","І повелів цар Хелкії священику, й Ахикаму, синові Шафановому, й Ахбору, синові Михеїному, і Шафану писареві, й Асаії, слузі царському, говорячи:","підіть, запитайте Господа про мене і про народ і про всю Юдею щодо слів цієї знайденої книги, бо великий гнів Господній, що запалав на нас за те, що не слухали батьки наші слів книги цієї, щоб чинити згідно з написаним для нас.","І пішов Хелкія священик, і Ахикам, і Ахбор, і Шафан, і Асаія до Олдами пророчиці, дружини Шаллума, сина Тикви, сина Хархаса, хоронителя одягу, — жила ж вона в Єрусалимі, у другій частині, — і говорили з нею.","І вона сказала їм: так говорить Господь, Бог Ізраїлів: скажіть чоловіку, який послав вас до мене:","так говорить Господь: наведу зло на місце це і на жителів його, — усі слова книги, яку читав цар Юдейський.","За те, що залишили Мене, і кадять іншим богам, щоб прогнівляти Мене всіма ділами рук своїх, запалав гнів Мій на місце це, і не погасне.","А царю Юдейському, який послав вас запитати Господа, скажіть: так говорить Господь Бог Ізраїлів, про слова, що ти чув:","оскільки пом’якшало серце твоє, і ти смирився перед Господом, почувши те, що Я прорік на місце це і на жителів його, що вони будуть предметом жаху і прокляття, і ти роздер одяг свій, і плакав переді Мною, то і Я почув тебе, говорить Господь.","За це, ось, Я приєднаю тебе до батьків твоїх, і ти покладений будеш у гробницю твою в мирі, і не побачать очі твої всього того лиха, яке Я наведу на місце це. І принесли цареві відповідь."],"x":{"1":"13.34.1","2":"30.49.4","3":"13.34.8","4":"12.6.13|13.34.9","5":"13.34.10","7":"11.12.15","8":"4.31.26|13.34.14","9":"13.34.16-17","10":"13.34.18","12":"13.34.20|32.26.24","14":"32.26.24|13.34.22","15":"13.34.23","16":"11.24.2|13.34.24","17":"4.31.29|11.23.26|32.7.20","19":"32.24.9|32.44.12|31.38.5","20":"31.57.2|11.23.30|13.35.24"}},{"v":["І послав цар, і зібрали до нього всіх старійшин Іуди та Єрусалима.","І пішов цар у дім Господній, і всі Юдеї, і всі жителі Єрусалима з ним, і священики, і пророки, і весь народ, від малого до великого, і прочитав, щоб чули вони всі слова книги завіту, знайденої в домі Господньому.","Потім став цар на підвищене місце й уклав перед лицем Господнім завіт — іти слідом Господа і дотримуватися заповідей Його й одкровень Його й уставів Його від усього серця і від усієї душі, щоб виконати слова завіту цього, написаного в книзі цій. І весь народ вступив у завіт.","І повелів цар Хелкії первосвященикові та іншим священикам, які стояли на сторожі біля порогу, винести з храму Господнього всі речі, зроблені для Ваала і для Астарти і для всього воїнства небесного, і спалив їх за Єрусалимом у долині Кедрон, і повелів порох їх віднести у Вефиль.","І відставив жерців, яких поставили царі юдейські, щоб звершувати куріння на висотах у містах юдейських і околицях Єрусалима, — і які кадили Ваалу, сонцю, і місяцю, і сузір’ям, і всьому воїнству небесному;","і виніс Астарту з дому Господнього за Єрусалим до потоку Кедрону, і спалив її біля потоку Кедрону, і стер її на порох, і кинув порох її на цвинтар загальнонародний;","і зруйнував доми блудилищні, які були при храмі Господньому, де жінки ткали одяг для Астарти;","і вивів усіх жерців з міст юдейських, і осквернив висоти, на яких звершували куріння жерці, від Геви до Вирсавії, і зруйнував висоти перед воротами, — ту, яка біля входу у ворота Ісуса градоначальника, і ту, яка на лівій стороні біля міських воріт.","Утім, жерці висот не приносили жертв на жертовнику Господньому в Єрусалимі, опрісноки ж їли разом із братами своїми.","І осквернив він Тофет, що на долині синів Еннома, щоб ніхто не проводив сина свого і дочки своєї через вогонь Молоху;","і відмінив коней, яких ставили царі юдейські сонцю перед входом у дім Господній біля кімнат Нефан-Мелеха євнуха, що у Фаруримі, колісниці ж сонця спалив вогнем.","І жертовники на покрівлі світлиці Ахазової, які зробили царі юдейські, і жертовники, які зробив Манассія на обох дворах дому Господнього, зруйнував цар, і скинув звідти, і викинув порох їх у потік Кедрон.","І висоти, що перед Єрусалимом, праворуч від Оливної гори, що спорудив Соломон, цар Ізраїлів, Астарті, мерзоті сидонській, і Хамосу, мерзоті моавитській, і Милхому, мерзоті аммонитській, осквернив цар;","і зруйнував статуї, і вирубав діброви, і наповнив місце їх кістками людськими.","Також і жертовник, що у Вефилі, висоту, споруджену Ієровоамом, сином Наватовим, який увів Ізраїля в гріх, — також і жертовник той і висоту він зруйнував, і спалив цю висоту, стер на порох, і спалив діброву.","І глянув Іосія і побачив могили, що були там на горі, і послав і взяв кістки з могил, і спалив на жертовнику, й осквернив його за словом Господнім, що проголосив чоловік Божий, який передрік події ці, [коли Ієровоам, під час свята, стояв перед жертовником. Потім, обернувшись, побачив могилу чоловіка Божого, який передрік ці події,]","і сказав Іосія : що це за пам’ятник, який я бачу? І сказали йому жителі міста: це могила чоловіка Божого, який приходив з Юдеї і проголосив про те, що ти робиш над жертовником Вефильським.","І сказав він: залиште його в спокої, ніхто не чіпай кісток його. І зберегли кістки його і кістки пророка, який приходив із Самарії.","Також і всі капища висот у містах самарійських, які побудували царі ізраїльські, прогнівляючи Господа , зруйнував Іосія, і зробив з ними те саме, що зробив у Вефилі;","і заколов усіх жерців висот, які там були, на жертовниках, і спалив кістки людські на них, — і повернувся в Єрусалим.","І повелів цар усьому народу, сказавши: «звершіть пасху Господу Богу вашому, як написано в цій книзі завіту», —","тому що не була звершена така пасха від днів суддів, які судили Ізраїля, і в усі дні царів ізраїльських і царів юдейських;","а у вісімнадцятий рік царя Іосії була звершена ця пасха Господу в Єрусалимі.","І викликателів мертвих, і чаклунів, і терафимів, і ідолів, і всі мерзоти, що з’являлися в землі Юдейській і в Єрусалимі, знищив Іосія, щоб виконати слова закону, написані в книзі, яку знайшов Хелкія священик у домі Господньому.","Подібного до нього не було царя раніше нього, який навернувся б до Господа всім серцем своїм, і всією душею своєю, і всіма силами своїми, за всім законом Мойсеєвим; і після нього не постав подібний до нього.","Однак Господь не відклав великої люті гніву Свого, якою запалав гнів Його на Іуду за всі образи, якими прогнівав Його Манассія.","І сказав Господь: і Іуду відкину від лиця Мого, як відкинув Я Ізраїля, і відкину місто це Єрусалим, яке Я обрав, і дім, про який Я сказав: «буде ім’я Моє там».","Інше про Іосію і про все, що він зробив, написано в літописі царів юдейських.","У дні його пішов фараон Нехао, цар Єгипетський, проти царя Ассирійського на ріку Євфрат. І вийшов цар Іосія назустріч йому, і той умертвив його в Мегиддоні, коли побачив його.","І раби його повезли його мертвого з Мегиддона, і привезли його в Єрусалим, і поховали його в гробниці його. І взяв народ землі Іоахаза, сина Іосіїного, і помазали його і поставили його царем замість батька його.","Двадцяти трьох років був Іоахаз, коли став царем, і три місяці царював у Єрусалимі; ім’я матері його Хамуталь, дочка Єремії, з Ливни.","І робив він неугодне в очах Господніх у всьому так, як робили батьки його.","І затримав його фараон Нехао в Ривлі, у землі Емафській, щоб він не царював у Єрусалимі, — і наклав пені на землю сто талантів срібла і [сто] талантів золота.","І поставив фараон Нехао царем Елиакима, сина Іосіїного, замість Іосії, батька його, і перемінив ім’я його на Іоакима; Іоахаза ж узяв і відвів у Єгипет, де він і помер.","І срібло і золото давав Іоаким фараонові; він зробив оцінку землі, щоб давати срібло за наказом фараона; від кожного з народу землі, за оцінкою своєю, він стягував срібло і золото для того, щоб віддавати фараонові Нехао.","Двадцяти п’яти років був Іоаким, коли став царем, і одинадцять років царював у Єрусалимі; ім’я матері його Зебудда, дочка Федаії, з Руми.","І робив він неугодне в очах Господніх у всьому так, як робили батьки його."],"x":{"1":"13.34.29","2":"13.34.30","3":"10.8.22|5.24.25|13.15.12","4":"30.49.3","5":"13.34.33","6":"11.21.3:7","7":"4.23.17","8":"13.34.5","10":"2.18.21","12":"6.6.25|11.11.18","13":"10.11.7","14":"13.34.5","15":"10.12.28","16":"10.13.2","17":"10.13.2:30","18":"10.13.31","21":"13.35.1|15.1.1","22":"13.35.18","23":"13.35.19","24":"13.35.20","25":"11.18.5|30.49.4","26":"11.22.17|32.15.4","27":"11.17.18|10.8.29","28":"13.34.1","29":"13.35.20","30":"11.22.20|13.35.23","31":"13.36.2|11.24.18","33":"13.36.3","34":"13.36.4|32.1.3","35":"13.36.4","37":"11.24.9"}},{"v":["У дні його виступив Навуходоносор, цар Вавилонський, і зробився Іоаким підвладним йому на три роки, але потім відійшов від нього.","І посилав на нього Господь полчища халдеїв, і полчища сиріян, і полчища моавитян, і полчища аммонитян, — посилав їх на Іуду, щоб погубити його за словом Господа, яке Він прорік через рабів Своїх пророків.","За велінням Господа було це з Іудою, щоб відкинути його від лиця Його за гріхи Манассії, за все, що він зробив;","і за кров невинну, яку він пролив, наповнивши Єрусалим кров’ю невинною, Господь не захотів простити.","Інше про Іоакима і про все, що він зробив, написано в літописі царів юдейських.","І спочив Іоаким з батьками своїми, і став царем Ієхонія, син його, замість нього.","Цар Єгипетський не виступав більше із землі своєї, тому що взяв цар Вавилонський усе, від потоку Єгипетського до ріки Євфрату, що належало цареві Єгипетському.","Вісімнадцяти років був Ієхонія, коли став царем, і три місяці царював у Єрусалимі; ім’я матері його Нехушта, дочка Елнафана, з Єрусалима.","І робив він неугодне в очах Господніх у всьому так, як робив батько його.","У той час підступили раби Навуходоносора, царя Вавилонського, до Єрусалима, й обложили місто.","І прийшов Навуходоносор, цар Вавилонський, до міста, коли раби його облягали його.","І вийшов Ієхонія, цар Юдейський, до царя Вавилонського, він і мати його, і слуги його, і князі його, і євнухи його, — і взяв його цар Вавилонський у восьмий рік свого царювання.","І вивіз він звідти всі скарби дому Господнього і скарби царського дому; і поламав, як прорік Господь, усі золоті сосуди, які Соломон, цар Ізраїлів, зробив у храмі Господньому;","і виселив весь Єрусалим, і всіх князів, і все хоробре військо, — десять тисяч було переселених, — і всіх теслів і ковалів; нікого не залишилося, крім бідного народу землі.","І переселив він Ієхонію у Вавилон; і матір царя, і дружин царя, і євнухів його, і сильних землі відвів на поселення з Єрусалима у Вавилон.","І все військо числом сім тисяч, і художників і будівельників тисячу, всіх хоробрих, які ходять на війну, відвів цар Вавилонський на поселення у Вавилон.","І поставив цар Вавилонський царем Матфанію, дядька Ієхонії , замість нього, і перемінив ім’я його на Седекію.","Двадцяти одного року був Седекія, коли став царем, і одинадцять років царював у Єрусалимі; ім’я матері його Хамуталь, дочка Єремії, з Ливни.","І робив він неугодне в очах Господніх у всьому так, як робив Іоаким.","Гнів Господній був над Єрусалимом і над Іудою до того, що Він відкинув їх від лиця Свого. І відійшов Седекія від царя Вавилонського."],"x":{"1":"13.36.6|37.1.1","2":"11.22.15|32.13.9","3":"11.21.11","4":"11.21.16","5":"13.36.5","6":"50.1.11","7":"0.15.18","8":"13.36.9","9":"11.23.32","10":"37.1.1","12":"32.22.24|32.29.2","13":"13.36.10|14.1.7|37.5.2","14":"20.2.6|31.3.3|32.29.2","15":"13.36.10|20.2.6","17":"32.37.1","18":"13.36.11|32.52.1","19":"11.23.32","20":"11.17.18|13.36.13"}},{"v":["У дев’ятий рік царювання свого, у десятий місяць, у десятий день місяця, прийшов Навуходоносор, цар Вавилонський, з усім військом своїм до Єрусалима, й обложив його, і спорудив навколо нього вал.","І перебувало місто в облозі до одинадцятого року царя Седекії.","У дев’ятий день місяця посилився голод у місті, і не було хліба у народу землі.","І взяте було місто, і побігли всі військові уночі по дорозі до воріт, між двома стінами, що біля царського саду; халдеї ж стояли навколо міста, і цар пішов дорогою до рівнини.","І погналося військо халдейське за царем, і наздогнали його на рівнинах єрихонських, і все військо його розбіглося від нього.","І взяли царя, і відвели його до царя Вавилонського в Ривлу, і вчинили над ним суд:","і синів Седекії закололи перед очима його, а самому Седекії осліпили очі і закували його в кайдани, і відвели його у Вавилон.","У п’ятий місяць, у сьомий день місяця, тобто в дев’ятнадцятий рік Навуходоносора, царя Вавилонського, прийшов Навузардан, начальник охоронців, слуга царя Вавилонського, в Єрусалим","і спалив дім Господній і дім царя, і всі доми в Єрусалимі, і всі доми великі спалив вогнем;","і стіни навколо Єрусалима зруйнувало військо халдейське, що було у начальника охоронців.","І інший народ, який залишався в місті, і перебіжчиків, які передалися цареві Вавилонському, й інший простий народ виселив Навузардан, начальник охоронців.","Тільки деяких із бідного народу землі залишив начальник охоронців працівниками у виноградниках і землеробами.","І стовпи мідні, які були в домі Господньому, і підстави, і море мідне, яке в домі Господньому, зламали халдеї, і віднесли мідь їх у Вавилон;","і тази, і лопатки, і ножі, і ложки, і всі посудини мідні, які вживалися при служінні, взяли;","і кадильниці, і чаші, що було золоте і що було срібне, узяв начальник охоронців:","стовпи числом два, море одне, і підстави, які зробив Соломон у дім Господній, — міді у всіх цих речах не було ваги.","Вісімнадцять ліктів висоти в одному стовпі; вінець на ньому мідний, а висота вінця три лікті, і сітка і гранатові яблука навколо вінця — усе з міді. Те саме і на іншому стовпі з сіткою.","І взяв начальник охоронців Сераію первосвященика і Цефанію, священика другого, і трьох, що стояли на варті біля порогу.","І з міста взяв одного євнуха, який був начальником над людьми військовими, і п’ять чоловік, які стояли перед лицем царя, що знаходилися в місті, і писаря головного у війську, який записував у військо народ землі, і шістдесят чоловік з народу землі, що знаходилися в місті.","І взяв їх Навузардан, начальник охоронців, і відвів їх до царя Вавилонського в Ривлу.","І вразив їх цар Вавилонський, і умертвив їх у Ривлі, у землі Емаф. І виселені були юдеї з землі своєї.","Над народом же, що залишався в землі Юдейській, який залишив Навуходоносор, цар Вавилонський, — над ними поставив начальником Годолію, сина Ахикама, сина Шафанового.","Коли почули всі воєначальники, вони і люди їхні, що цар Вавилонський поставив начальником Годолію, то прийшли до Годолії в Массифу, і саме : Ісмаїл, син Нефанії, й Іоханан, син Карея, і Сераія, син Танхумефа з Нетофафа, й Ієзанія, син маахитянина, вони і люди їхні.","І поклявся Годолія їм і людям їхнім, і сказав їм: не бійтеся бути підвладними халдеям, оселяйтеся на землі і служіть цареві Вавилонському, і буде добре вам.","Але в сьомий місяць прийшов Ісмаїл, син Нефанії, сина Елишами, з племені царського, з десятьма людьми, й уразив Годолію, і він помер, і юдеїв і халдеїв, які були з ним у Массифі.","І встав весь народ, від малого до великого, і воєначальники, і пішли в Єгипет, тому що боялися халдеїв.","У тридцять сьомий рік переселення Ієхонії, царя Юдейського, у дванадцятий місяць, у двадцять сьомий день місяця, Евилмеродах, цар Вавилонський, у рік, коли він став царем, вивів Ієхонію, царя Юдейського, із в’язниці","і говорив з ним дружньо, і поставив престіл його вище престолу царів, які були у нього у Вавилоні;","і перемінив в’язничний одяг його, і він завжди мав їжу в нього, в усі дні життя його.","І утримання його, утримання постійне, видаване було йому від царя, з дня у день, в усі дні життя його."],"x":{"1":"32.39.1|32.52.4","3":"32.52.6|33.4.10","4":"32.52.7","5":"32.52.8","6":"32.38.23|32.52.9|36.17.16","7":"32.39.6|32.52.11","8":"32.52.12","9":"25.73.7|36.16.41","10":"13.36.19","11":"13.36.20","12":"32.52.16","13":"32.27.19","14":"10.7.40|32.52.18","15":"32.52.19","16":"10.7.15:23","17":"10.7.15|13.3.15|32.52.21","18":"32.52.24","19":"32.52.25","21":"32.52.27","22":"32.40.5","23":"32.42.1","24":"32.40.9","26":"32.41.17|38.9.3","27":"32.52.31"}}];
export default C;
